async fn handle_modules_paths(
    method: &str,
    path: &str,
    body: &[u8],
) -> Result<Option<(u16, Vec<u8>, Option<String>)>, AdminError> {
    let trimmed = path.trim_matches('/');
    let parts = trimmed.split('/').collect::<Vec<_>>();
    if parts.first().copied() != Some("modules") {
        return Ok(None);
    }
    let storage_root = storage_root();
    let modules_root = storage_root.join("modules");
    match (method, parts.as_slice()) {
        ("GET", ["modules"]) => {
            let modules = list_dirs(&modules_root)?;
            let body = serde_json::json!({
                "status": "ok",
                "modules": modules,
            })
            .to_string()
            .into_bytes();
            Ok(Some((200, body, None)))
        }
        ("GET", ["modules", name]) => {
            let name = decode_percent(name);
            let versions = list_dirs(&modules_root.join(&name))?;
            let body = serde_json::json!({
                "status": "ok",
                "name": name,
                "versions": versions,
            })
            .to_string()
            .into_bytes();
            Ok(Some((200, body, None)))
        }
        ("GET", ["modules", name, version]) => {
            let name = decode_percent(name);
            let version = decode_percent(version);
            let module_path = modules_root.join(&name).join(&version);
            if !module_path.exists() {
                let body = serde_json::json!({
                    "status": "error",
                    "error_code": "NOT_FOUND",
                })
                .to_string()
                .into_bytes();
                return Ok(Some((404, body, None)));
            }
            if module_path.is_file() {
                let data = fs::read(&module_path)?;
                return Ok(Some((
                    200,
                    data,
                    Some("application/octet-stream".to_string()),
                )));
            }
            let mut builder = Builder::new(Vec::new());
            builder.append_dir_all(".", &module_path)?;
            let data = builder.into_inner()?;
            Ok(Some((200, data, Some("application/x-tar".to_string()))))
        }
        ("POST", ["modules", name, version]) => {
            let name = decode_percent(name);
            let version = decode_percent(version);
            let module_dir = modules_root.join(&name).join(&version);
            if module_dir.exists() {
                let body = serde_json::json!({
                    "status": "error",
                    "error_code": "MODULE_EXISTS",
                })
                .to_string()
                .into_bytes();
                return Ok(Some((409, body, None)));
            }
            fs::create_dir_all(&module_dir)?;
            let mut archive = Archive::new(Cursor::new(body));
            if let Err(err) = archive.unpack(&module_dir) {
                let _ = fs::remove_dir_all(&module_dir);
                let body = serde_json::json!({
                    "status": "error",
                    "error_code": "INVALID_ARCHIVE",
                    "error_detail": err.to_string(),
                })
                .to_string()
                .into_bytes();
                return Ok(Some((400, body, None)));
            }
            let body = serde_json::json!({
                "status": "ok",
                "name": name,
                "version": version,
            })
            .to_string()
            .into_bytes();
            Ok(Some((200, body, None)))
        }
        _ => Ok(None),
    }
}

fn decode_percent(input: &str) -> String {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let (Some(h), Some(l)) = (from_hex(bytes[i + 1]), from_hex(bytes[i + 2])) {
                out.push(h << 4 | l);
                i += 3;
                continue;
            }
        }
        if bytes[i] == b'+' {
            out.push(b' ');
        } else {
            out.push(bytes[i]);
        }
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn from_hex(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

fn storage_root() -> PathBuf {
    let default_root = json_router::paths::storage_root_dir();
    let hive_path = json_router::paths::config_dir().join("hive.yaml");
    let data = match fs::read_to_string(&hive_path) {
        Ok(data) => data,
        Err(_) => return default_root,
    };
    let parsed: HiveFile = match serde_yaml::from_str(&data) {
        Ok(parsed) => parsed,
        Err(_) => return default_root,
    };
    if let Some(path) = parsed.storage.and_then(|storage| storage.path) {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    default_root
}

fn list_dirs(path: &Path) -> Result<Vec<String>, AdminError> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let mut entries = Vec::new();
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        if entry.file_type()?.is_dir() {
            if let Some(name) = entry.file_name().to_str() {
                entries.push(name.to_string());
            }
        }
    }
    entries.sort();
    Ok(entries)
}

/// The most bytes a request's body may declare (FINDINGS A-234), above the largest body any action
/// takes: a package is at most a bundle_upload's zip at its cap (`BUNDLE_MAX_ZIP_BYTES`), and a
/// module's archive (`POST /modules/{name}/{version}`) or an inline package carries no more. A
/// request that declares more is answered 413 before its body is read (`HttpBodyTooLarge`).
const HTTP_BODY_MAX_BYTES: u64 = 1024 * 1024 * 1024;
const _: () = assert!(HTTP_BODY_MAX_BYTES > BUNDLE_MAX_ZIP_BYTES);

/// A request whose `Content-Length` passes `HTTP_BODY_MAX_BYTES`: nothing is allocated for its
/// body, nor is it read; the connection answers `413 BODY_TOO_LARGE` (`http_handler_error_response`),
/// then drops what the client still sends, for a while, before it closes
/// (`close_after_unread_request`).
#[derive(Debug)]
struct HttpBodyTooLarge {
    declared: u64,
}

impl std::fmt::Display for HttpBodyTooLarge {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "a request declared a body of {} bytes, past the {HTTP_BODY_MAX_BYTES} SY.admin reads",
            self.declared
        )
    }
}

impl std::error::Error for HttpBodyTooLarge {}

/// The most bytes a request's head may take, its request line and headers up to the blank line
/// that ends them (FINDINGS A-234). Past it, nothing more is read; the connection answers 431
/// (`HttpHeadersTooLarge`).
const HTTP_HEADER_MAX_BYTES: usize = 64 * 1024;

/// A request whose head passes `HTTP_HEADER_MAX_BYTES`: nothing more of it is read; the connection
/// answers `431 HEADERS_TOO_LARGE` (`http_handler_error_response`), then drops what the client
/// still sends, for a while, before it closes (`close_after_unread_request`).
#[derive(Debug)]
struct HttpHeadersTooLarge;

impl std::fmt::Display for HttpHeadersTooLarge {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "a request's headers passed the {HTTP_HEADER_MAX_BYTES} bytes SY.admin reads"
        )
    }
}

impl std::error::Error for HttpHeadersTooLarge {}

async fn read_http_request(
    stream: &mut tokio::net::TcpStream,
) -> Result<(String, String, HashMap<String, String>, Vec<u8>), AdminError> {
    let mut buf = Vec::new();
    let mut header_end = None;
    loop {
        let mut chunk = [0u8; 1024];
        let n = stream.read(&mut chunk).await?;
        if n == 0 {
            break;
        }
        buf.extend_from_slice(&chunk[..n]);
        if let Some(pos) = find_double_crlf(&buf) {
            header_end = Some(pos + 4);
            break;
        }
        if buf.len() > HTTP_HEADER_MAX_BYTES {
            return Err(Box::new(HttpHeadersTooLarge));
        }
    }
    let header_end = header_end.ok_or("invalid http request")?;
    if header_end > HTTP_HEADER_MAX_BYTES {
        return Err(Box::new(HttpHeadersTooLarge));
    }
    let header_str = String::from_utf8_lossy(&buf[..header_end]);
    let mut lines = header_str.split("\r\n");
    let request_line = lines.next().ok_or("missing request line")?;
    let mut parts = request_line.split_whitespace();
    let method = parts.next().ok_or("missing method")?.to_string();
    let path = parts.next().ok_or("missing path")?.to_string();
    let mut headers = HashMap::new();
    for line in lines {
        if line.is_empty() {
            continue;
        }
        if let Some((k, v)) = line.split_once(':') {
            headers.insert(k.trim().to_lowercase(), v.trim().to_string());
        }
    }
    let content_length = headers
        .get("content-length")
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(0);
    if content_length > HTTP_BODY_MAX_BYTES {
        return Err(Box::new(HttpBodyTooLarge {
            declared: content_length,
        }));
    }
    let content_length = content_length as usize;
    let mut body = buf[header_end..].to_vec();
    while body.len() < content_length {
        let mut chunk = vec![0u8; content_length - body.len()];
        let n = stream.read(&mut chunk).await?;
        if n == 0 {
            break;
        }
        body.extend_from_slice(&chunk[..n]);
    }
    Ok((method, path, headers, body))
}

fn find_double_crlf(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n")
}

fn split_path_query(path: &str) -> (&str, HashMap<String, String>) {
    if let Some((base, query)) = path.split_once('?') {
        (base, parse_query(query))
    } else {
        (path, HashMap::new())
    }
}

/// Query parameters, percent-decoded: a client that encodes `@` as `%40` (Python's urlencode does)
/// must match the same tap or route as one that sends it raw. `+` stays literal: raw `+` values
/// (an offset, a GMT+3 zone) are commoner here than form-encoded spaces.
fn parse_query(query: &str) -> HashMap<String, String> {
    let mut params = HashMap::new();
    for pair in query.split('&') {
        if pair.is_empty() {
            continue;
        }
        let (key, value) = match pair.split_once('=') {
            Some(parts) => parts,
            None => (pair, ""),
        };
        params.insert(decode_query_component(key), decode_query_component(value));
    }
    params
}

fn decode_query_component(input: &str) -> String {
    if !input.contains('%') {
        return input.to_string();
    }
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let (Some(h), Some(l)) = (from_hex(bytes[i + 1]), from_hex(bytes[i + 2])) {
                out.push(h << 4 | l);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

/// The `?hive=` of a global read (`/versions`, `/deployments`, `/drift-alerts`), trimmed: an empty
/// one is none, as each route's other filters are, and the read covers every hive (FINDINGS
/// A-297). Taken as given, an empty one asked the per-hive action with a hive of "", which the
/// orchestrator reads as its own: the motherbee's history answered for every hive's.
fn query_hive_filter(query: &HashMap<String, String>) -> Option<String> {
    query
        .get("hive")
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn deployments_payload_from_query(query: &HashMap<String, String>) -> serde_json::Value {
    let mut payload = serde_json::json!({});
    if let Some(limit_raw) = query.get("limit") {
        if let Ok(limit) = limit_raw.trim().parse::<u64>() {
            payload["limit"] = serde_json::Value::Number(limit.into());
        }
    }
    if let Some(category) = query
        .get("category")
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
    {
        payload["category"] = serde_json::Value::String(category.to_string());
    }
    payload
}

fn drift_alerts_payload_from_query(query: &HashMap<String, String>) -> serde_json::Value {
    let mut payload = deployments_payload_from_query(query);
    if let Some(severity) = query
        .get("severity")
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
    {
        payload["severity"] = serde_json::Value::String(severity.to_string());
    }
    if let Some(kind) = query
        .get("kind")
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
    {
        payload["kind"] = serde_json::Value::String(kind.to_string());
    }
    payload
}

fn is_mother_role(role: Option<&str>) -> bool {
    matches!(role.map(|r| r.trim().to_ascii_lowercase()), Some(ref r) if r == "motherbee")
}

fn http_status_line(status: u16) -> &'static str {
    match status {
        200 => "HTTP/1.1 200 OK",
        202 => "HTTP/1.1 202 Accepted",
        400 => "HTTP/1.1 400 Bad Request",
        403 => "HTTP/1.1 403 Forbidden",
        404 => "HTTP/1.1 404 Not Found",
        405 => "HTTP/1.1 405 Method Not Allowed",
        409 => "HTTP/1.1 409 Conflict",
        413 => "HTTP/1.1 413 Payload Too Large",
        422 => "HTTP/1.1 422 Unprocessable Entity",
        431 => "HTTP/1.1 431 Request Header Fields Too Large",
        500 => "HTTP/1.1 500 Internal Server Error",
        501 => "HTTP/1.1 501 Not Implemented",
        502 => "HTTP/1.1 502 Bad Gateway",
        503 => "HTTP/1.1 503 Service Unavailable",
        504 => "HTTP/1.1 504 Gateway Timeout",
        _ => "HTTP/1.1 500 Internal Server Error",
    }
}

fn error_code_to_http_status(error_code: &str) -> u16 {
    let code = error_code.trim().to_ascii_uppercase();
    if code == "TIMEOUT" || code == "WAN_TIMEOUT" || code == "SSH_TIMEOUT" {
        return 504;
    }
    // A join whose own session the new SSH rules would refuse (docs/control-path-hardening-v1.md
    // §6): the request has to change (ssh_allow_from, ssh_from_wan), not the transport.
    if code == "SSH_SOURCE_NOT_ALLOWED" || code == "SSH_FROM_WAN_LOCKOUT" {
        return 409;
    }
    if code.starts_with("SSH_") {
        return 502;
    }
    match code.as_str() {
        // Worker orchestrator is online but a socket op failed transiently
        // (add_hive did not fall back to SSH); the client should retry.
        "WORKER_SOCKET_UNREACHABLE" => 503,
        // A join found the box still settling (cloud-init or apt's daily jobs still running after
        // the wait): retry once it has (A-52).
        "HOST_NOT_SETTLED" => 503,
        "INVALID_REQUEST" | "INVALID_ADDRESS" | "INVALID_ARCHIVE" | "INVALID_HIVE_ID"
        | "INVALID_ZIP" | "INVALID_KEY_FORMAT" | "INVALID_VALUE" => 400,
        // A cursor its listing did not give (FINDINGS A-198): another listing's, or none at all.
        "INVALID_CURSOR" => 400,
        "UNAUTHORIZED"
        | "SYSTEM_ILK_PROTECTED"
        | "TENANT_ROOT_PROTECTED"
        // Only the core is born in the genesis tenant, and nobody registers there (D10).
        | "TENANT_ROOT_NOT_ALLOWED"
        | "TENANT_ROOT_NOT_REGISTRABLE" => 403,
        "NOT_FOUND"
        | "ILK_NOT_FOUND"
        | "TENANT_NOT_FOUND"
        | "NODE_NOT_FOUND"
        | "BLOB_NOT_FOUND"
        | "KEY_NOT_FOUND"
        | "RUNTIME_NOT_AVAILABLE"
        | "RUNTIME_NOT_FOUND"
        | "RUNTIME_VERSION_NOT_FOUND" => 404,
        // The work probably succeeded but the reply was lost — a conflict-with-current-state
        // answer, retryable once the operator has verified.
        "FORWARD_UNKNOWN"
        | "HIVE_EXISTS"
        // A join for this hive is already running in the background (PB-7): a conflict with
        // current state, and retryable once it finishes.
        | "JOIN_IN_PROGRESS"
        | "MODULE_EXISTS"
        | "VERSION_MISMATCH"
        | "VERSION_CONFLICT"
        | "NODE_INSTANCE_RUNNING"
        | "NODE_NOT_CONFIGURED"
        | "NOTHING_STAGED"
        | "NO_BACKUP"
        | "NO_PREVIOUS_VERSION"
        | "INSTANCES_ACTIVE"
        | "INSTANCES_UNKNOWN"
        | "STALE_CONFIG_VERSION"
        | "RUNTIME_IN_USE"
        // remove_runtime_version: some hive's nodes were not read, so the version's use is unknown
        // (FINDINGS A-281); nothing was removed, ask again.
        | "RUNTIME_USAGE_UNKNOWN"
        | "RUNTIME_HAS_DEPENDENTS"
        | "RUNTIME_CURRENT_CONFLICT"
        // A name another tenant holds: a vault key (one namespace for the hive), a tenant name or
        // domain.
        | "KEY_TAKEN"
        | "TENANT_NAME_TAKEN"
        | "TENANT_DOMAIN_TAKEN"
        // An identity lifecycle step the current state refuses: what blocks it is in the detail.
        | "TENANT_HAS_NODES"
        | "TENANT_HAS_CHILDREN"
        | "TENANT_HAS_PEOPLE"
        | "TENANT_NOT_DELETED"
        // A node of a tenant that is not active is not started (docs/ilk-tenant-model-v1.md §2.3).
        | "TENANT_NOT_ACTIVE"
        | "TENANT_DELETED"
        | "ILK_NOT_DELETED"
        | "ILK_KEY_CONFLICT"
        // retire_hive_ilks: the motherbee, or a hive the registry still lists (FINDINGS A-191).
        | "HIVE_NOT_REMOVED"
        // teardown_node: the ILK named is not the node's, or the node is still connected; nothing
        // was removed.
        | "NODE_ILK_MISMATCH"
        | "NODE_STILL_CONNECTED"
        // set_installation_ai (docs/hive-config-update-v1.md §4): what the motherbee's file holds,
        // or a node it would leave without an engine, refuses the change; nothing was written.
        | "NOT_PRIMARY"
        | "INSTALLATION_EDITED_BY_HAND"
        | "INSTALLATION_UNCHANGED"
        | "INSTALLATION_NOT_WRITTEN"
        | "NODES_LEFT_WITHOUT_ENGINE"
        | "PROVIDER_KEYS_MISSING"
        // A hive's copy of a version with another hash (update with category config).
        | "INSTALLATION_HASH_MISMATCH"
        // The installation's update: one explicit run at a time; a motherbee whose own core is
        // rolled back names no target.
        | "INSTALLATION_UPDATE_RUNNING"
        | "MOTHERBEE_ROLLED_BACK"
        | "BUSY" => 409,
        "COMPILE_ERROR"
        | "INVALID_CONFIG"
        // An installation ai a reader cannot use (set_installation_ai).
        | "INVALID_AI_SETTINGS"
        | "INVALID_PACKAGE_LAYOUT"
        | "UNSUPPORTED_APPLY_MODE"
        | "PACKAGE_PUBLISH_FAILED"
        // the stamped backup does not match its bytes: refuse rather than restore garbage
        | "BACKUP_CORRUPT" => 422,
        "INVALID_WORKFLOW_NAME" | "INVALID_CONFIG_SET" | "UNSUPPORTED_OPERATION" => 400,
        // The full action catalog asked over the mesh, where it never fits a frame (A-197), and
        // a node's answer the frame refused, sent as REPLY_TOO_LARGE in its place (A-198).
        "CATALOG_TOO_LARGE_FOR_MESH" | "REPLY_TOO_LARGE" => 413,
        "WORKFLOW_NOT_FOUND" => 404,
        // A WF engine's refusals of its instance verbs (`node_verb_answer`): an instance it does
        // not have, and one already ended.
        "INSTANCE_NOT_FOUND" => 404,
        "INSTANCE_ALREADY_TERMINATED" => 409,
        // SY.timer's refusals of the reads SY.admin's timer routes send it, in its own TIMER_*
        // vocabulary (docs/sy-timer.md §15, FINDINGS A-251): a request it cannot take (a cursor
        // that is not one, a malformed payload, a zone that is none), a timer it does not have,
        // its store failing, and a verb an SY.timer older than the route does not know.
        // TIMER_INTERNAL stays a 500.
        "TIMER_INVALID_PAYLOAD" | "TIMER_INVALID_TIMEZONE" => 400,
        "TIMER_NOT_FOUND" => 404,
        "TIMER_STORAGE_ERROR" => 502,
        "TIMER_UNKNOWN_VERB" => 501,
        // A store that failed: the WF engine's, or the file SY.cognition could not clear; and the
        // memory region SY.cognition could not write once its file was cleared (`cognition_clear`).
        "STORE_ERROR" | "REGION_ERROR" => 502,
        "NOT_IMPLEMENTED" => 501,
        "SERVICE_FAILED"
        | "SPAWN_FAILED"
        | "KILL_FAILED"
        | "REMOVE_FAILED"
        | "COPY_FAILED"
        | "CONFIG_FAILED"
        | "RUNTIME_ERROR"
        | "RUNTIME_COMMAND_FAILED"
        | "RUNTIME_UNAVAILABLE"
        | "RUNTIME_REMOVE_FAILED"
        | "ORCHESTRATOR_ERROR"
        | "RESTART_FAILED"
        | "STORAGE_ERROR"
        | "ENCRYPTION_ERROR"
        | "TRANSPORT_ERROR"
        // add_hive could not check whether the box had settled (A-52); not about settling.
        | "HOST_SETTLE_CHECK_FAILED"
        // add_hive could not push the spoke's mesh TLS material (D32); fatal for the join.
        | "TLS_PUSH_FAILED"
        // teardown_node: a store did not do its step; the report says which.
        | "TEARDOWN_INCOMPLETE"
        // SY.wf-rules made a definition current, and its WF node does not run it: the spawn or
        // the restart failed (`wf_node` in the payload says which).
        | "WF_NODE_NOT_DEPLOYED"
        // The motherbee's installation file or its record could not be read or written; a hive's
        // readers took a config update whose record it could not write.
        | "INSTALLATION_RECORDS_UNREADABLE"
        | "INSTALLATION_UNREADABLE"
        | "INSTALLATION_WRITE_FAILED"
        | "CONFIG_RECORD_FAILED"
        // update_installation could not name the motherbee's core, its target.
        | "INSTALLATION_TARGET_UNKNOWN" => 502,
        // A worker behind the egress (docs/edge-egress-nat-spec.md §15): a refusal before anything
        // changed, what the switch met and reverted, and what nobody answered.
        "NOT_A_WORKER"
        | "NO_EGRESS_DECLARED"
        | "NO_REACHABILITY_URL"
        | "EGRESS_SWITCH_OPEN"
        | "GATEWAY_NOT_ON_LINK"
        | "UPLINK_ON_DEFAULT_ROUTE"
        | "ACCESS_ON_DEFAULT_ROUTE"
        | "DEFAULT_ROUTE_MULTIPATH"
        | "PROBE_UNAVAILABLE"
        | "PREVIOUS_GATEWAY_UNKNOWN" => 409,
        "EGRESS_DECLARATION_INVALID" => 422,
        "EGRESS_PROBE_FAILED"
        | "EGRESS_IPV6_UNMANAGED"
        | "UPLINK_ROUTE_CHANGED"
        | "EGRESS_SWITCH_FAILED"
        | "EGRESS_COMMIT_FAILED"
        | "EGRESS_RECORD_FAILED"
        | "EGRESS_RECORD_UNREADABLE"
        | "EGRESS_CONFIRM_UNREADABLE"
        | "EGRESS_SWITCH_NOT_FOUND" => 502,
        "HIVE_UNREACHABLE" | "EGRESS_GUARD_UNREADABLE" => 503,
        "EGRESS_CONFIRM_MISSED" | "EGRESS_NOT_ANSWERED" => 504,
        "SHM_NOT_FOUND"
        | "RUNTIME_MANIFEST_MISSING"
        | "MISSING_WAN_LISTEN"
        | "IDENTITY_UNAVAILABLE"
        | "VAULT_UNAVAILABLE"
        // The connected nodes cannot be read from shared memory: retry.
        | "INVENTORY_UNAVAILABLE"
        // set_installation_ai could not read every hive's AI nodes, or the vault's key names, for
        // its checks: retry once they answer.
        | "HIVES_NOT_CHECKED"
        | "KEYS_NOT_CHECKED"
        // The hive registry cannot be read: the hives an installation update reaches are unknown.
        | "HIVE_REGISTRY_UNREADABLE"
        | "MASTER_KEY_NOT_AVAILABLE" => 503,
        _ => 500,
    }
}

fn infer_transport_error_code(error_detail: &str) -> &'static str {
    let lower = error_detail.to_ascii_lowercase();
    if lower.contains("timeout") || lower.contains("timed out") {
        "TIMEOUT"
    } else {
        "TRANSPORT_ERROR"
    }
}

fn value_string_field(value: &serde_json::Value, field: &str) -> Option<String> {
    value
        .get(field)
        .and_then(|v| v.as_str())
        .map(|v| v.to_string())
}

fn payload_error_code(payload: &serde_json::Value) -> Option<String> {
    value_string_field(payload, "error_code").or_else(|| {
        payload
            .get("error")
            .and_then(|value| value.get("code"))
            .and_then(|value| value.as_str())
            .map(|value| value.to_string())
    })
}

fn payload_error_detail(payload: &serde_json::Value) -> Option<String> {
    value_string_field(payload, "error_detail")
        .or_else(|| value_string_field(payload, "message"))
        .or_else(|| {
            payload
                .get("error")
                .and_then(|value| value.get("detail"))
                .and_then(|value| value.as_str())
                .map(|value| value.to_string())
        })
        .or_else(|| {
            payload
                .get("error")
                .and_then(|value| value.get("message"))
                .and_then(|value| value.as_str())
                .map(|value| value.to_string())
        })
}

/// The statuses that count as SUCCESS on the wire, i.e. not an error envelope.
///
/// Three are not literally `"ok"`, and each is deliberate:
/// - `not_found`: a well-formed query whose answer is "nothing here".
/// - `sync_pending`: the target correctly refused a stale update; the caller must re-sync.
/// - `accepted`: the work was taken but is NOT finished — `add_hive` runs in the background
///   (PB-7) and the caller polls `GET /hives/<id>`. Anything else answering `accepted` inherits
///   the same 202 contract, so add it here only if that is what you mean.
fn is_ok_status(status: Option<&str>) -> bool {
    matches!(
        status,
        Some(value)
            if value.eq_ignore_ascii_case("ok")
                || value.eq_ignore_ascii_case("not_found")
                || value.eq_ignore_ascii_case("sync_pending")
                || value.eq_ignore_ascii_case("accepted")
    )
}

fn payload_is_ok(payload: &serde_json::Value) -> bool {
    if is_ok_status(payload.get("status").and_then(|v| v.as_str())) {
        return true;
    }
    payload
        .get("ok")
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
}

async fn respond_json(
    stream: &mut tokio::net::TcpStream,
    status: u16,
    body: &str,
) -> Result<(), AdminError> {
    let status_line = http_status_line(status);
    let response = format!(
        "{status_line}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        body.len(),
        body
    );
    stream.write_all(response.as_bytes()).await?;
    Ok(())
}

async fn respond_bytes(
    stream: &mut tokio::net::TcpStream,
    status: u16,
    content_type: &str,
    body: &[u8],
) -> Result<(), AdminError> {
    let status_line = http_status_line(status);
    let header = format!(
        "{status_line}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\n\r\n",
        body.len()
    );
    stream.write_all(header.as_bytes()).await?;
    stream.write_all(body).await?;
    Ok(())
}

fn next_opa_version(requested: Option<u64>) -> Result<u64, AdminError> {
    // Read, decide and write as one step: every mesh command runs in its own task (A-68), and two
    // OPA writes at once must not take the same version.
    static COUNTER: std::sync::Mutex<()> = std::sync::Mutex::new(());
    let _counter = COUNTER
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let path = json_router::paths::opa_version_path();
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let current = fs::read_to_string(&path)
        .ok()
        .and_then(|data| data.trim().parse::<u64>().ok())
        .unwrap_or(0);
    let next = match requested {
        Some(version) => {
            if version <= current {
                return Err(
                    format!("version must be greater than current (current={current})").into(),
                );
            }
            version
        }
        None => current + 1,
    };
    // A write cut short leaves the counter as it was, never empty: an empty one reads as 0.
    let staged = path.with_extension("next");
    let written = (|| -> std::io::Result<()> {
        let mut file = fs::File::create(&staged)?;
        file.write_all(next.to_string().as_bytes())?;
        file.sync_all()?;
        fs::rename(&staged, &path)
    })();
    if let Err(err) = written {
        let _ = fs::remove_file(&staged);
        return Err(err.into());
    }
    Ok(next)
}

async fn handle_opa_http(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    mut req: OpaRequest,
    action: OpaAction,
) -> Result<(u16, String), AdminError> {
    // One user policy for every hive (decided 2026-09-30): the motherbee's SY.opa.rules compiles,
    // applies and publishes it; every other hive installs what it publishes. There is no
    // per-hive policy to write.
    if let Some(hive) = normalize_opa_target(req.hive.take()) {
        if hive != PRIMARY_HIVE_ID {
            let resp = serde_json::json!({
                "status": "error",
                "error_code": "INVALID_REQUEST",
                "error_detail": format!(
                    "there is one user policy for every hive; '{hive}' cannot have its own (use /opa/policy)"
                ),
            });
            return Ok((400, resp.to_string()));
        }
    }
    let primary = Some(PRIMARY_HIVE_ID.to_string());
    let entrypoint = req
        .entrypoint
        .clone()
        .unwrap_or_else(|| "router/target".to_string());

    if action.needs_rego() && req.rego.as_deref().unwrap_or("").is_empty() {
        let resp = serde_json::json!({
            "status": "error",
            "error_code": "COMPILE_ERROR",
            "error_detail": "rego_missing"
        });
        return Ok((400, resp.to_string()));
    }

    // A check is a read: it takes no version, and the motherbee stages and applies nothing.
    if action.check_only() {
        let rego = req.rego.clone().unwrap_or_default();
        let responses = send_opa_check(client, rego, entrypoint).await?;
        return Ok(build_opa_http_response(
            ctx, action, None, responses, primary,
        ));
    }

    let version = match action {
        OpaAction::Apply => {
            let Some(version) = req.version else {
                let resp = serde_json::json!({
                    "status": "error",
                    "error_code": "VERSION_MISMATCH",
                    "error_detail": "version_required"
                });
                return Ok((400, resp.to_string()));
            };
            version
        }
        OpaAction::Rollback => req.version.unwrap_or(0),
        OpaAction::Clear => 0,
        _ => next_opa_version(req.version)?,
    };

    let mut responses = Vec::new();
    if matches!(action, OpaAction::Compile | OpaAction::CompileApply) {
        responses = send_opa_action(
            ctx,
            client,
            "compile",
            version,
            req.rego.clone(),
            Some(entrypoint.clone()),
            action.auto_apply_flag(),
        )
        .await?;
        let compiled = !responses.is_empty() && responses.iter().all(|r| r.status == "ok");
        if !compiled || !action.apply_after() {
            return Ok(build_opa_http_response(
                ctx,
                action,
                Some(version),
                responses,
                primary,
            ));
        }
    }

    // The step that changes the running policy, on the motherbee.
    let step = if action.apply_after() {
        "apply"
    } else {
        action.as_str()
    };
    let step_responses = send_opa_action(ctx, client, step, version, None, None, None).await?;
    let step_answered = !step_responses.is_empty();
    let applied = step_responses
        .iter()
        .find(|r| r.hive == PRIMARY_HIVE_ID && r.status.eq_ignore_ascii_case("ok"))
        .cloned();
    responses.extend(step_responses);
    let Some(applied) = applied else {
        if !step_answered {
            // The compile answer must not make this look like a success: the step that changes
            // the running policy got no answer, so nobody knows whether it changed.
            let body = serde_json::json!({
                "status": "error",
                "version": version,
                "action": action.write_name(),
                "responses": responses,
                "error_code": "TIMEOUT",
                "error_detail": format!(
                    "SY.opa.rules@{PRIMARY_HIVE_ID} did not answer the {step} within {OPA_PRIMARY_WAIT_SECS} s; \
                     the policy may or may not have changed (check GET /hives/{PRIMARY_HIVE_ID}/opa/status)"
                ),
            })
            .to_string();
            return Ok((error_code_to_http_status("TIMEOUT"), body));
        }
        return Ok(build_opa_http_response(
            ctx,
            action,
            Some(version),
            responses,
            primary,
        ));
    };

    // Applied and published on the motherbee: tell every hive, and report who runs it already.
    // The others are pending, not failed — they install it when the published file reaches them.
    let hash = applied.hash.clone().unwrap_or_default();
    scan_published_opa_policy(client).await;
    let expected = opa_rollout_hives(ctx);
    let reachable = topology_hives_from_lsa(ctx);
    let mut receiver = client.subscribe(RPC_BC_CONFIG_RESPONSE)?;
    send_opa_sync_notice(client, version, &hash).await?;
    let synced = collect_opa_responses(
        &mut receiver,
        "sync",
        OpaAnswerTo::Version(version),
        Some(&hash),
        &expected,
        Duration::from_secs(OPA_SYNC_WAIT_SECS),
    )
    .await;
    Ok(build_opa_rollout_response(
        action, version, &hash, responses, synced, &expected, &reachable,
    ))
}

/// How long a write waits for the motherbee's SY.opa.rules, and then for the other hives to report
/// they run the published policy. A reachable hive answers in a few seconds (it re-checks every
/// second after the notice); one that does not is reported pending — it converges later on its
/// own — instead of holding the caller past its own timeout.
const OPA_PRIMARY_WAIT_SECS: u64 = 30;
const OPA_SYNC_WAIT_SECS: u64 = 10;
/// The Syncthing folder that carries the published policy, how long the orchestrator may spend on
/// its scan, and how long a write waits for that answer (a hint, never a gate).
const OPA_POLICY_SYNC_FOLDER: &str = "fluxbee-dist-policy";
const OPA_POLICY_SCAN_TIMEOUT_MS: u64 = 3_000;
const OPA_POLICY_SCAN_WAIT_SECS: u64 = 5;

/// Have the motherbee's Syncthing pick up the policy just published now, not when its filesystem
/// watcher gets to it: a clear only renames and deletes files, which the watcher holds for its
/// full timeout (measured: 60 s, against 10 s when a new wasm is written). The orchestrator owns
/// Syncthing; its sync hint scans the folder and waits until it is idle — the same step a runtime
/// publish takes. Best effort: without it the hives still converge, later.
async fn scan_published_opa_policy(client: &RouterDispatcher) {
    let request = serde_json::json!({
        "channel": "dist",
        "folder_id": OPA_POLICY_SYNC_FOLDER,
        "wait_for_idle": true,
        "timeout_ms": OPA_POLICY_SCAN_TIMEOUT_MS,
    });
    // Bounded: with Syncthing unhealthy the orchestrator may take long on this hint, and the
    // write must not wait for it — the hives still find the file on their own checks.
    match send_system_request(
        client,
        &format!("SY.orchestrator@{PRIMARY_HIVE_ID}"),
        "SYSTEM_SYNC_HINT",
        "SYSTEM_SYNC_HINT_RESPONSE",
        request,
        Duration::from_secs(OPA_POLICY_SCAN_WAIT_SECS),
    )
    .await
    {
        Ok(payload) if payload.get("status").and_then(|v| v.as_str()) == Some("ok") => {
            tracing::info!("opa: published policy scanned on the motherbee")
        }
        Ok(payload) => tracing::warn!(
            payload = %payload,
            "opa: scan of the published policy did not complete; the hives get it on the next scan"
        ),
        Err(err) => tracing::warn!(
            error = %err,
            "opa: no answer to the scan of the published policy; the hives get it on the next scan"
        ),
    }
}

fn build_opa_rollout_response(
    action: OpaAction,
    version: u64,
    hash: &str,
    responses: Vec<OpaResponseEntry>,
    synced: Vec<OpaResponseEntry>,
    expected: &[String],
    reachable: &[String],
) -> (u16, String) {
    let running: Vec<String> = synced
        .iter()
        .filter(|entry| entry.status.eq_ignore_ascii_case("ok"))
        .map(|entry| entry.hive.clone())
        .collect();
    let pending: Vec<String> = expected
        .iter()
        .filter(|hive| !running.contains(hive))
        .cloned()
        .collect();
    // Pending hives the motherbee cannot reach now: they keep their last policy until they
    // reconnect and Syncthing catches up.
    let unreachable: Vec<String> = pending
        .iter()
        .filter(|hive| !reachable.contains(hive))
        .cloned()
        .collect();
    let body = serde_json::json!({
        "status": "ok",
        "version": version,
        "action": action.write_name(),
        "hash": hash,
        "responses": responses,
        "hives": synced,
        "running_hives": running,
        "pending": pending,
        "unreachable": unreachable,
        "converged": pending.is_empty(),
    })
    .to_string();
    (200, body)
}

async fn handle_opa_query(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    action: &str,
    target: Option<String>,
) -> Result<(u16, String), AdminError> {
    let responses = send_opa_query(ctx, client, action, target.clone()).await?;
    Ok(build_opa_query_response(ctx, action, responses, target))
}

/// The config SY.wf-rules gets for an operation: the request, the operation, and who asked for it
/// (`launched_by`, stamped by the admin, never taken from the request), which SY.wf-rules carries
/// into the run_node of a first deploy.
fn wf_rules_operation_config(
    mut payload: serde_json::Map<String, serde_json::Value>,
    operation: &str,
    launched_by: &str,
) -> serde_json::Value {
    payload.insert("operation".to_string(), serde_json::json!(operation));
    payload.insert("launched_by".to_string(), serde_json::json!(launched_by));
    serde_json::Value::Object(payload)
}

/// The config of a check (`send_wf_rules_check`): the request, the operation and the check's id.
/// It takes no version, and no `launched_by`: a check launches nothing.
fn wf_rules_check_config(
    mut payload: serde_json::Map<String, serde_json::Value>,
    check_id: &str,
) -> serde_json::Value {
    payload.remove("version");
    payload.remove("launched_by");
    payload.insert("operation".to_string(), serde_json::json!("check"));
    payload.insert("check_id".to_string(), serde_json::json!(check_id));
    serde_json::Value::Object(payload)
}

/// SY.wf-rules' answer to the check `check_id`, and to no other: it echoes the id it checked, in a
/// pass and in a refusal. An answer without it ran no check (an SY.wf-rules that knows no check
/// compiles and stages instead), so it is an error, never a pass.
fn wf_rules_check_answer(
    target_node: &str,
    check_id: &str,
    answer: serde_json::Value,
) -> Result<serde_json::Value, AdminError> {
    match answer.get("check_id").and_then(serde_json::Value::as_str) {
        Some(echoed) if echoed == check_id => Ok(answer),
        echoed => Err(format!(
            "invalid response for check {check_id}: {target_node} answered check_id {}, so it ran no check",
            echoed.unwrap_or("none")
        )
        .into()),
    }
}

/// A check is a read (docs/wf-orchestration-v1.md §5.5.1): the hive's SY.wf-rules validates the
/// definition as a compile does and only answers. It takes no version and writes nothing (no
/// staged definition, no package, no store row), so a check between a compile and its apply leaves
/// the staged and the current definitions alone. A fresh `check_id`, echoed in the answer, ties the
/// two together, as `send_opa_check` does.
async fn send_wf_rules_check(
    client: &RouterDispatcher,
    target_node: &str,
    payload: serde_json::Map<String, serde_json::Value>,
) -> Result<serde_json::Value, AdminError> {
    let check_id = Uuid::new_v4().to_string();
    let config = wf_rules_check_config(payload, &check_id);
    let answer = send_wf_rules_config_set(client, target_node, config).await?;
    wf_rules_check_answer(target_node, &check_id, answer)
}

/// An operation of SY.wf-rules, as the node `CONFIG_SET` contract carries it.
async fn send_wf_rules_config_set(
    client: &RouterDispatcher,
    target_node: &str,
    config: serde_json::Value,
) -> Result<serde_json::Value, AdminError> {
    send_system_request_with_meta(
        client,
        target_node,
        "CONFIG_SET",
        "CONFIG_RESPONSE",
        serde_json::json!({
            "node_name": target_node,
            "schema_version": 1,
            "config_version": 0,
            "apply_mode": "replace",
            "config": config,
        }),
        16,
        None,
        None,
        Some(target_node.to_string()),
        Some("CONFIG_SET".to_string()),
        None,
        wf_rules_request_timeout(),
    )
    .await
}

/// `launched_by`: who asked (`operator` on the HTTP API; launched_by_for_caller over the mesh).
async fn handle_wf_rules_http(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    req: WfRulesRequest,
    action: WfRulesAction,
    launched_by: &str,
) -> Result<(u16, String), AdminError> {
    let target_hive = normalize_wf_rules_target(req.hive.clone(), &ctx.hive_id);
    let target_node = format!("SY.wf-rules@{}", target_hive);
    let response = if action.check_only() {
        send_wf_rules_check(client, &target_node, req.payload).await
    } else if let Some(operation) = action.operation() {
        let config = wf_rules_operation_config(req.payload, operation, launched_by);
        send_wf_rules_config_set(client, &target_node, config).await
    } else if let Some(command) = action.command() {
        send_l2_action_request(
            client,
            &target_node,
            "command",
            command,
            serde_json::Value::Object(req.payload),
            wf_rules_request_timeout(),
        )
        .await
    } else {
        Err("unsupported wf-rules action".into())
    };
    let answer = build_admin_http_response(action.action_name(), response);
    if !matches!(action, WfRulesAction::Delete) {
        return Ok(answer);
    }
    // A workflow's delete purges its WF node through kill_node, refused for no page (FINDINGS
    // A-242): its ok answer names the node's pages left up, the node as SY.wf-rules names it.
    Ok(with_pages_left_up(answer, |payload| {
        let node_name = payload
            .pointer("/wf_node/node_name")
            .and_then(|value| value.as_str())
            .map(str::trim)
            .filter(|node_name| !node_name.is_empty())?;
        Some(pages_left_up(ctx, &PagesOf::Node(node_name.to_string())))
    }))
}

/// How long the admin waits for SY.wf-rules: longer than the deadline SY.wf-rules gives a request
/// end to end (60 s: publish, purge, waiting for the package to reach a worker, the node's rebind
/// and restart or launch), so the answer is never lost to a timeout while the deploy goes on; Archi
/// waits longer still (90 s). A-68.
fn wf_rules_request_timeout() -> Duration {
    Duration::from_secs(env_timeout_secs("JSR_ADMIN_WF_RULES_TIMEOUT_SECS").unwrap_or(75))
}

async fn handle_wf_rules_query(
    _ctx: &AdminContext,
    client: &RouterDispatcher,
    action: &str,
    req: WfRulesRequest,
) -> Result<(u16, String), AdminError> {
    let target_hive = normalize_wf_rules_target(req.hive.clone(), "");
    let target_node = if target_hive.is_empty() {
        return Err("wf-rules target hive is required".into());
    } else {
        format!("SY.wf-rules@{}", target_hive)
    };
    let response = send_l2_action_request(
        client,
        &target_node,
        "query",
        action,
        serde_json::Value::Object(req.payload),
        wf_rules_request_timeout(),
    )
    .await;
    Ok(build_admin_http_response(action, response))
}

fn wf_rules_request_from_query(
    mut query: HashMap<String, String>,
    default_hive: Option<String>,
) -> WfRulesRequest {
    let explicit_hive = query.remove("hive");
    let explicit_target = query.remove("target");
    let hive = explicit_hive.or(explicit_target).or(default_hive);
    WfRulesRequest {
        payload: query
            .into_iter()
            .map(|(key, value)| (key, serde_json::json!(value)))
            .collect(),
        hive,
    }
}

fn normalize_wf_rules_target(target: Option<String>, fallback_hive: &str) -> String {
    target
        .and_then(|value| {
            let trimmed = value.trim().to_string();
            if trimmed.is_empty() || trimmed.eq_ignore_ascii_case("broadcast") {
                None
            } else {
                Some(trimmed)
            }
        })
        .unwrap_or_else(|| fallback_hive.to_string())
}

async fn send_l2_action_request(
    client: &RouterDispatcher,
    target: &str,
    msg_type: &str,
    action: &str,
    payload: serde_json::Value,
    timeout_window: Duration,
) -> Result<serde_json::Value, AdminError> {
    let sender = client.sender_snapshot();
    let msg = Message {
        routing: Routing {
            src: sender.uuid().to_string(),
            src_l2_name: None,
            dst: Destination::Unicast(target.to_string()),
            ttl: 16,
            trace_id: String::new(),
        },
        meta: Meta {
            msg_type: msg_type.to_string(),
            action: Some(action.to_string()),
            target: Some(target.to_string()),
            action_class: classify_admin_action(action),
            ..Meta::default()
        },
        payload,
    };
    let success = match msg_type {
        "command" => vec![
            RouteMatch::any_msg_type("command"),
            RouteMatch::any_msg_type("command_response"),
        ],
        "query" => vec![
            RouteMatch::any_msg_type("query"),
            RouteMatch::any_msg_type("query_response"),
        ],
        _ => {
            return Err(format!("unsupported l2 action msg_type={msg_type}").into());
        }
    };
    let matcher = PendingMatcher::new(
        success,
        vec![
            RouteMatch::exact(SYSTEM_KIND, MSG_UNREACHABLE),
            RouteMatch::exact(SYSTEM_KIND, MSG_TTL_EXCEEDED),
        ],
        vec![],
    );
    let msg = client
        .send_with_matcher(
            msg,
            matcher,
            RpcRequestLabels::new(target, action, msg_type),
            timeout_window,
        )
        .await?;

    let response_msg_type = msg.meta.msg_type.as_str();
    let expected_ok = match msg_type {
        "command" => response_msg_type == "command" || response_msg_type == "command_response",
        "query" => response_msg_type == "query" || response_msg_type == "query_response",
        _ => false,
    };
    if !expected_ok {
        return Err(format!(
            "invalid response type for {}: expected {} got {}",
            action, msg_type, response_msg_type
        )
        .into());
    }
    let action_matches = msg.meta.action.as_deref() == Some(action)
        || msg.meta.msg.as_deref() == Some(&format!("{}_RESPONSE", action.to_uppercase()));
    if !action_matches {
        return Err(format!(
            "invalid response action for {}: got action={:?} msg={:?}",
            action, msg.meta.action, msg.meta.msg
        )
        .into());
    }
    Ok(msg.payload)
}

async fn handle_timer_rpc(
    _ctx: &AdminContext,
    client: &RouterDispatcher,
    action: &str,
    timer_msg: &str,
    payload: serde_json::Value,
    hive_id: String,
) -> Result<(u16, String), AdminError> {
    let target = format!("SY.timer@{}", hive_id);
    let normalized_payload = if payload.is_null() {
        serde_json::json!({})
    } else {
        payload
    };
    let response = send_system_request(
        client,
        &target,
        timer_msg,
        "TIMER_RESPONSE",
        normalized_payload,
        admin_action_timeout(action),
    )
    .await;
    Ok(build_admin_http_response(action, response))
}

/// `GET /hives/{hive}/streams` (A-70, docs/router-stream-v1.md §2.10): asks every router stream of
/// the hive, the `RT.<router>.stream@<hive>` nodes the LSA lists for it, for its status. A stream
/// that does not answer is listed with its error.
async fn handle_list_streams(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    hive_id: String,
) -> Result<(u16, String), AdminError> {
    let action = "list_streams";
    let Some(streams) = stream_nodes_from_lsa(ctx, &hive_id) else {
        return Ok((
            404,
            serde_json::json!({
                "status": "error",
                "action": action,
                "payload": serde_json::Value::Null,
                "error_code": "HIVE_NOT_FOUND",
                "error_detail": format!("hive '{hive_id}' is not in this router's LSA"),
            })
            .to_string(),
        ));
    };
    let timeout_window = admin_action_timeout(action);
    let answers = futures::future::join_all(streams.iter().map(|node| {
        send_system_request(
            client,
            node,
            MSG_STREAM_STATUS,
            MSG_STREAM_STATUS_RESPONSE,
            serde_json::json!({}),
            timeout_window,
        )
    }))
    .await;
    let items: Vec<serde_json::Value> = streams
        .iter()
        .zip(answers)
        .map(|(node, answer)| match answer {
            Ok(status) => serde_json::json!({ "node": node, "status": status }),
            Err(err) => serde_json::json!({
                "node": node,
                "status": serde_json::Value::Null,
                "error": err.to_string(),
            }),
        })
        .collect();
    Ok((
        200,
        serde_json::json!({
            "status": "ok",
            "action": action,
            "payload": { "hive": hive_id, "streams": items },
            "error_code": serde_json::Value::Null,
            "error_detail": serde_json::Value::Null,
        })
        .to_string(),
    ))
}

/// The router streams the LSA lists for `hive_id`, by L2 name; None when the hive is not in it.
fn stream_nodes_from_lsa(ctx: &AdminContext, hive_id: &str) -> Option<Vec<String>> {
    let shm_name = format!("/jsr-lsa-{}", ctx.hive_id);
    let snapshot = LsaRegionReader::open_read_only(&shm_name)
        .ok()?
        .read_snapshot()?;
    let hive_index = snapshot
        .hives
        .iter()
        .position(|entry| remote_hive_name(entry).as_deref() == Some(hive_id))?;
    let mut streams: Vec<String> = snapshot
        .nodes
        .iter()
        .filter(|node| node.hive_index as usize == hive_index)
        .filter(|node| node.name_len > 0 && node.flags & FLAG_DELETED == 0)
        .map(|node| {
            let len = (node.name_len as usize).min(node.name.len());
            let name = String::from_utf8_lossy(&node.name[..len]).into_owned();
            if name.contains('@') {
                name
            } else {
                format!("{name}@{hive_id}")
            }
        })
        .filter(|name| is_stream_node_name(name))
        .collect();
    streams.sort();
    streams.dedup();
    Some(streams)
}

async fn handle_admin_query(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    action: &str,
    hive: Option<String>,
) -> Result<(u16, String), AdminError> {
    if action == "list_admin_actions" {
        return Ok(build_admin_actions_catalog_response(AdminCatalogView::Full));
    }
    if action == "list_cloud_actions" {
        return Ok(build_cloud_actions_catalog_response());
    }
    if matches!(action, "list_ilks" | "list_tenants") {
        return handle_identity_query(ctx, client, action, serde_json::json!({}), hive).await;
    }
    if matches!(action, "list_nodes" | "list_tenant_nodes" | "list_versions") {
        return handle_paged_orchestrator_query(ctx, client, action, serde_json::json!({}), hive)
            .await;
    }
    let payload = normalize_admin_payload(action, serde_json::json!({}), hive.as_deref());
    let request = build_admin_request(ctx, action, payload, hive);
    let response = send_admin_request(
        client,
        request,
        admin_action_timeout(action),
        &admin_node_name(&ctx.hive_id),
    )
    .await;
    // /versions carries the installation's update (docs/hive-config-update-v1.md §7, stage 4).
    let response =
        installation_update::with_update_summary(&ctx.installation_update, action, response);
    Ok(build_admin_http_response(action, response))
}

/// `list_nodes`, `list_tenant_nodes` and `list_versions` (FINDINGS A-198): the orchestrator answers
/// a page of nodes, or of hives' snapshots, within half a frame, and SY.admin assembles the pages
/// (`orchestrator_list_pages`): without a `limit`, every node or hive, as before the pages.
async fn handle_paged_orchestrator_query(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    action: &str,
    payload: serde_json::Value,
    hive: Option<String>,
) -> Result<(u16, String), AdminError> {
    let caller = match PageAsk::from_payload(&payload) {
        Ok(caller) => caller,
        Err(detail) => return Ok(admin_invalid_request_response(action, &detail)),
    };
    let response = orchestrator_list_pages(ctx, client, action, &payload, hive, &caller).await;
    // /versions carries the installation's update (docs/hive-config-update-v1.md §7, stage 4).
    let response =
        installation_update::with_update_summary(&ctx.installation_update, action, response);
    Ok(build_admin_http_response(action, response))
}

/// An orchestrator listing, `list_nodes` and `list_tenant_nodes` (their `nodes`) or `list_versions`
/// (its `hives`), assembled from its pages (`assemble_list_pages`) as the caller asks it. `list_versions`' comparison is
/// each page's against the motherbee's snapshot, joined (`merge_versions_comparisons`).
async fn orchestrator_list_pages(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    action: &str,
    payload: &serde_json::Value,
    hive: Option<String>,
    caller: &PageAsk,
) -> Result<serde_json::Value, AdminError> {
    let rows_key = if action == "list_versions" {
        "hives"
    } else {
        "nodes"
    };
    let comparisons = std::sync::Mutex::new(Vec::new());
    let relay = admin_node_name(&ctx.hive_id);
    let within = admin_action_timeout(action);
    let mut assembled = assemble_list_pages(rows_key, caller, within, |page, left| {
        let mut request = payload.clone();
        page.apply_to(&mut request);
        let request = normalize_admin_payload(action, request, hive.as_deref());
        let request = build_admin_request(ctx, action, request, hive.clone());
        let (comparisons, relay) = (&comparisons, &relay);
        async move {
            let answer = send_admin_request(client, request, left, relay).await?;
            if let Some(comparison) = answer.get("comparison") {
                comparisons
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .push(comparison.clone());
            }
            Ok(answer)
        }
    })
    .await?;
    let comparisons = comparisons
        .into_inner()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if comparisons.len() > 1 && payload_is_ok(&assembled) {
        assembled["comparison"] = merge_versions_comparisons(&comparisons);
    }
    Ok(assembled)
}

/// `list_versions`' comparison over its pages (FINDINGS A-198): every page compares its hives with
/// the motherbee's snapshot, so the hives' verdicts join, and the verdict is the worst of the
/// pages': `differs`, then `unknown`, then `match`.
fn merge_versions_comparisons(pages: &[serde_json::Value]) -> serde_json::Value {
    let verdict_of = |page: &serde_json::Value| {
        page.get("verdict")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("unknown")
            .to_string()
    };
    let verdict = if pages.iter().any(|page| verdict_of(page) == "differs") {
        "differs"
    } else if pages.iter().any(|page| verdict_of(page) != "match") {
        "unknown"
    } else {
        "match"
    };
    let hives: Vec<serde_json::Value> = pages
        .iter()
        .filter_map(|page| page.get("hives").and_then(serde_json::Value::as_array))
        .flatten()
        .cloned()
        .collect();
    let mut merged = pages
        .first()
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    merged["verdict"] = serde_json::json!(verdict);
    merged["hives"] = serde_json::Value::Array(hives);
    merged
}

async fn handle_admin_query_with_payload(
    ctx: &AdminContext,
    client: &RouterDispatcher,
    action: &str,
    payload: serde_json::Value,
    hive: Option<String>,
) -> Result<(u16, String), AdminError> {
    if action == "list_cloud_actions" {
        return Ok(build_cloud_actions_catalog_response());
    }
    // The identity listings take their filters (include_deleted, pending_signup) straight to
    // SY.identity, as the HTTP route does.
    if matches!(action, "list_ilks" | "list_tenants") {
        return handle_identity_query(ctx, client, action, payload, hive).await;
    }
    if matches!(action, "list_nodes" | "list_tenant_nodes" | "list_versions") {
        return handle_paged_orchestrator_query(ctx, client, action, payload, hive).await;
    }
    let payload = normalize_admin_payload(action, payload, hive.as_deref());
    let request = build_admin_request(ctx, action, payload, hive);
    let response = send_admin_request(
        client,
        request,
        admin_action_timeout(action),
        &admin_node_name(&ctx.hive_id),
    )
    .await;
    let response =
        installation_update::with_update_summary(&ctx.installation_update, action, response);
    Ok(build_admin_http_response(action, response))
}

/// What `list_admin_actions` answers (FINDINGS A-197): every field of each action, or its compact
/// form, which fits one mesh frame.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AdminCatalogView {
    /// Each action's `name`, `description` and `read_only`: what Archi's plan compiler and its
    /// reads use. An action's schema is its own help (`get_admin_action_help`).
    Compact,
    /// Each action's routes, request contract, executor schema and example: some 330 KB in
    /// 0.1.121, more than one mesh frame (`MAX_FRAME_SIZE`, 128 KiB), so HTTP's alone.
    Full,
}

impl AdminCatalogView {
    fn as_str(self) -> &'static str {
        match self {
            AdminCatalogView::Compact => "compact",
            AdminCatalogView::Full => "full",
        }
    }
}

/// The view a `list_admin_actions` request names (`view`), else its path's: full over HTTP, the one
/// path with no frame, and compact over the mesh and to the executor, whose answer goes back to
/// Archi over the mesh inside the plan's result: the full catalog never fits a frame. Asked off
/// HTTP, `full` is refused (`CATALOG_TOO_LARGE_FOR_MESH`), never answered with a reply the frame
/// refuses and the caller waits on until its timeout.
fn admin_catalog_view(
    named: Option<&str>,
    over_http: bool,
) -> Result<AdminCatalogView, (&'static str, String)> {
    let view = match named.map(str::trim).filter(|view| !view.is_empty()) {
        None if over_http => AdminCatalogView::Full,
        None => AdminCatalogView::Compact,
        Some(view) if view.eq_ignore_ascii_case("compact") => AdminCatalogView::Compact,
        Some(view) if view.eq_ignore_ascii_case("full") => AdminCatalogView::Full,
        Some(other) => {
            return Err((
                "INVALID_REQUEST",
                format!("view '{other}' is not one list_admin_actions answers: compact or full"),
            ))
        }
    };
    if !over_http && view == AdminCatalogView::Full {
        return Err((
            "CATALOG_TOO_LARGE_FOR_MESH",
            "the full action catalog does not fit in one mesh frame (128 KiB): ask view compact \
             (each action's name, description and read_only), read one action's schema with \
             get_admin_action_help, or read the full catalog over HTTP (GET /admin/actions)"
                .to_string(),
        ));
    }
    Ok(view)
}

/// One action of the compact catalog (FINDINGS A-197).
fn build_admin_action_compact_doc(spec: &InternalActionSpec) -> serde_json::Value {
    serde_json::json!({
        "name": spec.action,
        "description": admin_action_summary(spec.action),
        "read_only": admin_action_is_read_only(spec.action),
    })
}

fn admin_actions_catalog_envelope(view: AdminCatalogView) -> serde_json::Value {
    let actions: Vec<serde_json::Value> = INTERNAL_ACTION_REGISTRY
        .iter()
        .map(match view {
            AdminCatalogView::Compact => build_admin_action_compact_doc,
            AdminCatalogView::Full => build_admin_action_doc,
        })
        .collect();
    serde_json::json!({
        "status": "ok",
        "action": "list_admin_actions",
        "payload": {
            "registry_version": INTERNAL_ACTION_REGISTRY_VERSION,
            "view": view.as_str(),
            "actions": actions,
        },
        "error_code": serde_json::Value::Null,
        "error_detail": serde_json::Value::Null,
    })
}

fn build_admin_actions_catalog_response(view: AdminCatalogView) -> (u16, String) {
    (200, admin_actions_catalog_envelope(view).to_string())
}

/// `list_admin_actions` refused: an unknown view, or the full catalog asked off HTTP.
fn admin_catalog_view_refusal(code: &str, detail: &str) -> serde_json::Value {
    serde_json::json!({
        "status": "error",
        "action": "list_admin_actions",
        "payload": serde_json::Value::Null,
        "error_code": code,
        "error_detail": detail,
    })
}

/// Capability query for IO.cloud / Fluxbee Cloud: the SAME registry projection as
/// `build_admin_actions_catalog_response`, but filtered to `IO_CLOUD_EXPOSED_ACTIONS` — so Cloud
/// discovers exactly the provisioning surface it may invoke (create tenant, put token, spawn node)
/// from ONE source, never a duplicated hardcoded list. The relay authz gate reads the same
/// `IO_CLOUD_EXPOSED_ACTIONS`, so advertised == enforced.
fn build_cloud_actions_catalog_response() -> (u16, String) {
    let exposed: std::collections::HashSet<&str> =
        IO_CLOUD_EXPOSED_ACTIONS.iter().copied().collect();
    let actions: Vec<serde_json::Value> = INTERNAL_ACTION_REGISTRY
        .iter()
        .filter(|spec| exposed.contains(spec.action))
        .map(build_admin_action_doc)
        .collect();
    (
        200,
        serde_json::json!({
            "status": "ok",
            "action": "list_cloud_actions",
            "payload": {
                "registry_version": INTERNAL_ACTION_REGISTRY_VERSION,
                "actions": actions,
            },
            "error_code": serde_json::Value::Null,
            "error_detail": serde_json::Value::Null,
        })
        .to_string(),
    )
}

fn build_admin_action_help_response(action_name: &str) -> (u16, String) {
    let action_name = action_name.trim();
    let Some(spec) = INTERNAL_ACTION_REGISTRY
        .iter()
        .find(|spec| spec.action == action_name)
    else {
        return (
            404,
            serde_json::json!({
                "status": "error",
                "action": "get_admin_action_help",
                "payload": serde_json::Value::Null,
                "error_code": "ACTION_NOT_FOUND",
                "error_detail": format!("unknown admin action '{}'", action_name),
            })
            .to_string(),
        );
    };

    (
        200,
        serde_json::json!({
            "status": "ok",
            "action": "get_admin_action_help",
            "payload": {
                "registry_version": INTERNAL_ACTION_REGISTRY_VERSION,
                "entry": build_admin_action_doc(spec),
            },
            "error_code": serde_json::Value::Null,
            "error_detail": serde_json::Value::Null,
        })
        .to_string(),
    )
}

fn build_admin_executor_function_catalog_response(
    ctx: &AdminContext,
) -> Result<(u16, String), AdminError> {
    let node_config = load_admin_executor_node_config(&ctx.hive_id)?;
    let catalog = build_admin_executor_function_catalog(node_config.as_ref());
    let mode = admin_executor_catalog_mode(node_config.as_ref());
    Ok((
        200,
        serde_json::json!({
            "status": "ok",
            "action": "admin_executor_function_catalog",
            "payload": {
                "node_name": ctx.node_name,
                "catalog_mode": mode,
                "registry_version": INTERNAL_ACTION_REGISTRY_VERSION,
                "function_count": catalog.len(),
                "override_actions": ADMIN_EXECUTOR_SCHEMA_OVERRIDE_ACTIONS,
                "functions": catalog,
            },
            "error_code": serde_json::Value::Null,
            "error_detail": serde_json::Value::Null,
        })
        .to_string(),
    ))
}

/// Model D' — reject any secret-bearing field on the executor CONFIG_SET
/// surface. OpenAI credentials live entirely in vault under
/// `resource_type=openai`; the executor resolves them at boot/refresh.
fn reject_admin_executor_secret_fields(payload: &serde_json::Value) -> Result<(), AdminError> {
    let config_root = payload.get("config").unwrap_or(payload);
    if config_root.get("ai_providers").is_some() || config_root.get("ai").is_some() {
        return Err(
            "AI provider/model are the installation's: its installation file holds them \
             (docs/hive-config-update-v1.md §4), not this node's config"
                .into(),
        );
    }
    Ok(())
}

fn merge_admin_executor_local_config(
    existing: Option<AdminExecutorNodeConfigFile>,
    payload: &serde_json::Value,
) -> Result<(AdminExecutorNodeConfigFile, bool), AdminError> {
    let mut merged = existing.unwrap_or_default();
    if merged.schema_version == 0 {
        merged.schema_version = ADMIN_EXECUTOR_CONFIG_SCHEMA_VERSION;
    }
    let mut changed = false;
    let config_root = payload.get("config").unwrap_or(payload);

    if let Some(catalog) = config_root
        .get("catalog")
        .and_then(serde_json::Value::as_object)
    {
        let catalog_cfg = merged
            .catalog
            .get_or_insert_with(AdminExecutorCatalogConfig::default);
        if let Some(value) = catalog.get("mode") {
            let mode = value
                .as_str()
                .map(str::trim)
                .filter(|v| !v.is_empty())
                .ok_or("config.catalog.mode must be a non-empty string")?;
            if mode != "full" && mode != "subset" {
                return Err("config.catalog.mode must be 'full' or 'subset'".into());
            }
            catalog_cfg.mode = Some(mode.to_string());
            changed = true;
        }
        if let Some(value) = catalog.get("actions") {
            let values = value
                .as_array()
                .ok_or("config.catalog.actions must be an array of admin action names")?;
            let mut actions = Vec::new();
            for entry in values {
                let action = entry
                    .as_str()
                    .map(str::trim)
                    .filter(|v| !v.is_empty())
                    .ok_or("config.catalog.actions entries must be non-empty strings")?;
                resolve_internal_action_spec(action).map_err(|err| {
                    format!("config.catalog.actions contains invalid action '{action}': {err}")
                })?;
                if !admin_action_executor_available(action) {
                    return Err(format!(
                        "config.catalog.actions contains mesh-only action '{action}', which is not available to the admin executor"
                    )
                    .into());
                }
                actions.push(action.to_string());
            }
            catalog_cfg.actions = Some(actions);
            changed = true;
        }
    }

    Ok((merged, changed))
}

fn build_admin_executor_config_get_payload(
    ctx: &AdminContext,
) -> Result<serde_json::Value, AdminError> {
    let node_config = load_admin_executor_node_config(&ctx.hive_id)?;
    let hive = load_hive(&json_router::paths::config_dir())?;
    let (settings, engine) = hive_ai_settings(&hive).map_err(|reason| -> AdminError {
        format!("SY.admin's ai settings cannot be used: {reason}").into()
    })?;
    let config_version = node_config
        .as_ref()
        .map(|cfg| cfg.config_version)
        .unwrap_or(0);
    let schema_version = node_config
        .as_ref()
        .map(|cfg| cfg.schema_version)
        .unwrap_or(ADMIN_EXECUTOR_CONFIG_SCHEMA_VERSION);
    // "configured" reflects what the *runtime* actually resolved (vault may
    // be unreachable or empty), not local config.
    let configured = ctx.executor_configured.load(Ordering::Relaxed);
    let resources = serde_json::json!([
        {
            "resource_type": engine.provider.to_string(),
            "required": true,
            "configured": configured,
            "scope": "pool (tenant or root)"
        }
    ]);

    Ok(serde_json::json!({
        "ok": true,
        "node_name": ctx.node_name,
        "state": if configured { "configured" } else { "missing_secret" },
        "schema_version": schema_version,
        "config_version": config_version,
        "config": {
            "ai": {
                "default_provider": engine.provider.to_string(),
                "model": engine.model,
                "source": ai_settings::ai_source_json(&settings.source)
            },
            "catalog": {
                "mode": admin_executor_catalog_mode(node_config.as_ref()),
                "actions": node_config
                    .as_ref()
                    .and_then(|cfg| cfg.catalog.as_ref())
                    .and_then(|catalog| catalog.actions.clone())
                    .map(serde_json::Value::from)
                    .unwrap_or(serde_json::Value::Null)
            }
        },
        "contract": {
            "node_family": "SY",
            "node_kind": "SY.admin",
            "supports": ["CONFIG_GET", "CONFIG_SET"],
            "required_fields": [],
            "optional_fields": [
                "config.catalog.mode",
                "config.catalog.actions"
            ],
            "resources": resources,
            "notes": [
                "The AI provider/model are the installation's, in its installation file (hive.yaml's ai while this hive holds none; config.ai.source says which), and cannot be overridden by CONFIG_SET.",
                "Catalog mode defaults to full. Use subset only when intentionally constraining the executor-visible action set."
            ]
        },
        "function_count": build_admin_executor_function_catalog(node_config.as_ref()).len()
    }))
}

fn admin_executor_config_error_response(
    ctx: &AdminContext,
    code: &str,
    message: &str,
) -> Result<serde_json::Value, AdminError> {
    let base = build_admin_executor_config_get_payload(ctx)?;
    Ok(base
        .as_object()
        .cloned()
        .map(|mut value| {
            value.insert("ok".to_string(), serde_json::Value::Bool(false));
            value.insert(
                "error".to_string(),
                serde_json::json!({
                    "code": code,
                    "message": message
                }),
            );
            serde_json::Value::Object(value)
        })
        .unwrap_or_else(|| {
            serde_json::json!({
                "ok": false,
                "node_name": ctx.node_name,
                "state": "error",
                "error": {
                    "code": code,
                    "message": message
                }
            })
        }))
}

async fn apply_admin_executor_config_set(
    ctx: &AdminContext,
    msg: &Message,
) -> Result<serde_json::Value, AdminError> {
    let requested_node_name = msg
        .payload
        .get("node_name")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or("config-set requires node_name")?;
    if requested_node_name != ctx.node_name {
        return admin_executor_config_error_response(
            ctx,
            "invalid_config",
            "config-set node_name does not match this node",
        );
    }
    if let Some(apply_mode) = msg
        .payload
        .get("apply_mode")
        .and_then(serde_json::Value::as_str)
    {
        if !apply_mode.trim().eq_ignore_ascii_case("replace") {
            return admin_executor_config_error_response(
                ctx,
                "unsupported_apply_mode",
                "SY.admin executor currently supports only apply_mode=replace",
            );
        }
    }

    // Model D' — reject secret-bearing fields up-front. OpenAI credentials
    // live entirely in vault under resource_type=openai.
    if let Err(err) = reject_admin_executor_secret_fields(&msg.payload) {
        return admin_executor_config_error_response(ctx, "invalid_config", &err.to_string());
    }
    let current_config = load_admin_executor_node_config(&ctx.hive_id)?;
    let current_version = current_config
        .as_ref()
        .map(|cfg| cfg.config_version)
        .unwrap_or(0);
    let (mut merged_config, config_changed) =
        match merge_admin_executor_local_config(current_config, &msg.payload) {
            Ok(value) => value,
            Err(err) => {
                return admin_executor_config_error_response(
                    ctx,
                    "invalid_config",
                    &err.to_string(),
                );
            }
        };
    if !config_changed {
        return admin_executor_config_error_response(
            ctx,
            "invalid_config",
            "config-set requires at least one executor catalog field (catalog.mode, catalog.actions)",
        );
    }

    merged_config.schema_version = msg
        .payload
        .get("schema_version")
        .and_then(serde_json::Value::as_u64)
        .map(|value| value as u32)
        .unwrap_or(ADMIN_EXECUTOR_CONFIG_SCHEMA_VERSION);
    merged_config.config_version = msg
        .payload
        .get("config_version")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or_else(|| current_version.saturating_add(1));

    let _ = save_admin_executor_node_config(&ctx.hive_id, &merged_config)?;

    let configured = refresh_admin_executor_ai_runtime(ctx, VaultWait::Once).await?;
    Ok(serde_json::json!({
        "ok": true,
        "node_name": ctx.node_name,
        "state": if configured { "configured" } else { "missing_secret" },
        "schema_version": merged_config.schema_version,
        "config_version": merged_config.config_version,
        "apply_mode": "replace",
        "config": {
            "catalog": {
                "mode": admin_executor_catalog_mode(Some(&merged_config)),
                "actions": merged_config.catalog.as_ref().and_then(|catalog| catalog.actions.clone()).map(serde_json::Value::from).unwrap_or(serde_json::Value::Null)
            }
        },
        "message": "SY.admin executor catalog config persisted; AI provider/model remain hive-wide."
    }))
}

fn build_admin_action_doc(spec: &InternalActionSpec) -> serde_json::Value {
    let path_patterns = admin_action_path_patterns(spec.action);
    let execution_preference = admin_action_execution_preference(spec.action);
    let (handler, canonical_action) = match spec.route {
        InternalActionRoute::Query(canonical) => ("query", Some(canonical)),
        InternalActionRoute::Command(canonical) => ("command", Some(canonical)),
        InternalActionRoute::Update => ("update", None),
        InternalActionRoute::SyncHint => ("sync_hint", None),
        InternalActionRoute::Inventory => ("inventory", None),
        InternalActionRoute::OpaHttp(_) => ("opa_http", None),
        InternalActionRoute::OpaQuery(canonical) => ("opa_query", Some(canonical)),
        InternalActionRoute::WfRulesHttp(_) => ("wf_rules_http", None),
        InternalActionRoute::WfRulesQuery(canonical) => ("wf_rules_query", Some(canonical)),
        InternalActionRoute::TimerRpc(canonical) => ("timer_rpc", Some(canonical)),
        InternalActionRoute::StreamStatus => ("stream_status", None),
        InternalActionRoute::LlmUsage => ("llm_usage", None),
        InternalActionRoute::Acme => ("acme", None),
        InternalActionRoute::WebStatus => ("web_status", None),
        InternalActionRoute::Installation => ("installation", None),
    };
    serde_json::json!({
        "name": spec.action,
        "action": spec.action,
        "handler": handler,
        "canonical_action": canonical_action,
        "requires_target": spec.requires_target,
        "allow_legacy_hive_id": spec.allow_legacy_hive_id,
        "read_only": admin_action_is_read_only(spec.action),
        "confirmation_required": admin_action_requires_confirmation(spec.action),
        "executor_available": admin_action_executor_available(spec.action),
        "description": admin_action_summary(spec.action),
        "summary": admin_action_summary(spec.action),
        "path_patterns": path_patterns,
        "path_patterns_are_templates": !path_patterns.is_empty(),
        "execution_preference": execution_preference,
        "request_contract": admin_action_request_contract(spec.action),
        "executor_contract": admin_action_executor_contract(spec),
    })
}

/// The executor's note on a secret's resource type (FINDINGS A-164): the SDK's list of types, and
/// the types the product's own nodes read, each with what reads it and the value it expects.
static VAULT_RESOURCE_TYPES_NOTE: LazyLock<String> = LazyLock::new(|| {
    format!(
        "Model D' for vault_put / vault_rotate: metadata.resource_type is MANDATORY (canonical lowercase snake_case). A consumer that resolves its secret by type (an AI node's provider key) finds it only under that exact type. The SDK's resource types: {}. The product's own nodes also use: tls (the edge's certificate, value {{cert, key}}: SY.admin's ACME writes it in the root tenant with the edge as its owner, and SY.edge reads it by its tls_vault_key), whatsapp (io.wapp reads it by its key and requires this type, value {{access_token, app_secret, verify_token}}) and linkedhelper_adapter (io.linkedhelper reads it by its key, value a string or {{adapter_secret}}). Any other type must be the one its consumer reads, and must already normalize cleanly. metadata.tenant_id defaults to the hive's root tenant when omitted (infrastructure-wide secret, readable by every SY system caller). To scope a secret to a specific node, use metadata.owner_node (a friendly L2 like 'SY.architect' — admin resolves the ILK); omit it entirely to publish to the tenant pool. metadata.owner_ilk is REJECTED (legacy Model J) — do not generate it.",
        fluxbee_sdk::ResourceType::known_wire_values().join(", ")
    )
});

fn admin_action_executor_contract(spec: &InternalActionSpec) -> serde_json::Value {
    if !admin_action_executor_available(spec.action) {
        return serde_json::json!({
            "kind": "unavailable",
            "available": false,
            "function_schema": serde_json::Value::Null,
            "description": "This action requires the router-stamped identity of the producer and cannot run through the HTTP/operator admin executor.",
            "notes": [
                "Call RouterDispatcher::send_admin_rpc from the AI.*, IO.* or WF.* producer process.",
                "The producer must not supply or override src_l2_name, tenant_id or publisher_l2_name."
            ],
        });
    }
    let schema = build_admin_executor_function_definition(spec).parameters_json_schema;
    let notes = if matches!(
        spec.action,
        "vault_list"
            | "vault_put"
            | "vault_get"
            | "vault_get_metadata"
            | "vault_delete"
            | "vault_rotate"
            | "vault_rollback"
            | "vault_assign"
            | "core_rollback"
    ) {
        vec![
            "Executor plans must put path params and JSON body fields directly under step.args.",
            "Do not wrap mutation fields under args.body; body is only the HTTP request shape.",
            "Vault value-bearing fields are secret-sensitive and must not be printed in summaries/logs.",
            "Prefer vault_get_metadata for inspection. Use vault_get only when the operator explicitly needs the secret value.",
            VAULT_RESOURCE_TYPES_NOTE.as_str(),
            "Postgres secrets MUST be credentials + host only — never include a dbname in the connection string. Each consumer (storage, identity, architect-messages-db, cognition) applies its own dbname after resolving. Example value: {\"postgres_url\": \"postgresql://user:pass@host:5432\"}.",
        ]
    } else if matches!(
        spec.action,
        "create_tenant" | "update_tenant" | "set_tenant_sponsor"
    ) {
        vec![
            "Executor plans must put path params and JSON body fields directly under step.args.",
            "Do not wrap mutation fields under args.body; body is only the HTTP request shape.",
            "Tenant hierarchy uses sponsor_tenant_id directly in args, for example \"$steps.s1.payload.tenant_id\".",
            "For update_tenant, use args.tenant_id plus args.name/status/domain/settings/sponsor_tenant_id directly.",
        ]
    } else {
        vec![
            "Executor plans must put path params and JSON body fields directly under step.args.",
            "Do not wrap mutation fields under args.body unless function_schema explicitly defines a body property.",
            "Step output references may use $steps.<step_id>.<path>.",
        ]
    };
    serde_json::json!({
        "kind": "flat_function_args",
        "arg_shape": "flat_object",
        "description": "Exact executor step.args schema. This is distinct from the HTTP request_contract body shape.",
        "function_schema": schema,
        "notes": notes,
    })
}

/// An action only a producer asks for, over the mesh: the router-stamped caller is the publisher,
/// so it has no HTTP route, and the executor, which runs every step as the operator, has no
/// producer to act for. Taking a page down is not one (A-120): the operator takes down any page,
/// on loopback or through a plan Archi stages and the operator confirms, and an AI node still asks
/// over the mesh for its own.
fn admin_action_is_mesh_only(action: &str) -> bool {
    action == "publish_artifact"
}

fn admin_action_executor_available(action: &str) -> bool {
    !admin_action_is_mesh_only(action)
}

fn admin_action_execution_preference(action: &str) -> &'static str {
    if admin_action_is_mesh_only(action) {
        "mesh_admin_rpc_from_producer"
    } else {
        "example_scmd"
    }
}

fn admin_action_is_read_only(action: &str) -> bool {
    !matches!(
        action,
        "add_hive"
            // It mints the endpoint's bearer token and answers it once (FINDINGS A-198 found it
            // and the identity writes below listed as reads).
            | "publish_cloud_endpoint"
            | "set_ilk_definition"
            | "delete_ilk"
            | "restore_ilk"
            | "set_ilk_tenant"
            | "purge_ilk"
            | "create_tenant"
            | "update_tenant"
            | "set_tenant_sponsor"
            | "delete_tenant"
            | "restore_tenant"
            | "purge_tenant"
            | "publish_runtime_package"
            | "publish_artifact"
            | "unpublish_artifact"
            | "remove_hive"
            | "retire_hive_ilks"
            | "add_route"
            | "delete_route"
            | "add_vpn"
            | "delete_vpn"
            | "add_tap"
            | "delete_tap"
            | "run_node"
            | "start_node"
            | "restart_node"
            | "kill_node"
            | "remove_node_instance"
            | "teardown_node"
            | "remove_runtime_version"
            | "reset_base_runtime"
            | "set_node_config"
            | "node_control_config_set"
            | "send_node_message"
            | "set_storage"
            | "vault_put"
            | "vault_delete"
            | "vault_rotate"
            | "vault_rollback"
            | "vault_assign"
            | "core_rollback"
            | "set_hive_egress"
            | "clear_hive_egress"
            | "update"
            | "sync_hint"
            | "opa_compile_apply"
            | "opa_compile"
            | "opa_apply"
            | "opa_rollback"
            | "opa_clear"
            | "wf_rules_compile_apply"
            | "wf_rules_compile"
            | "wf_rules_apply"
            | "wf_rules_rollback"
            | "wf_rules_delete"
            | "wf_cancel_instance"
            | "cognition_clear"
            | "set_installation_ai"
            | "update_installation"
            | "acme_renew"
            | "acme_test"
            | "acme_reload"
    )
}

fn admin_action_requires_confirmation(action: &str) -> bool {
    matches!(
        action,
        "publish_runtime_package"
            | "remove_hive"
            // The system ILKs of a removed hive leave every lookup (reversible).
            | "retire_hive_ilks"
            | "delete_route"
            | "delete_vpn"
            | "delete_tap"
            | "kill_node"
            | "remove_node_instance"
            | "teardown_node"
            | "remove_runtime_version"
            // Every node that follows the runtime's current moves onto another build.
            | "reset_base_runtime"
            | "set_ilk_definition"
            | "delete_ilk"
            | "restore_ilk"
            | "set_ilk_tenant"
            | "purge_ilk"
            | "delete_tenant"
            | "restore_tenant"
            | "purge_tenant"
            | "set_node_config"
            | "node_control_config_set"
            | "set_storage"
            | "create_tenant"
            | "update_tenant"
            | "set_tenant_sponsor"
            | "vault_put"
            | "vault_get"
            | "vault_delete"
            | "vault_rotate"
            | "vault_rollback"
            | "vault_assign"
            | "core_rollback"
            | "update"
            | "sync_hint"
            | "opa_compile_apply"
            | "opa_compile"
            | "opa_apply"
            | "opa_rollback"
            | "opa_clear"
            // It ends a conversation that is running: the operator says so first.
            | "wf_cancel_instance"
            | "acme_renew"
            | "acme_test"
            // It takes down a page that people may be reading, whoever published it.
            | "unpublish_artifact"
            // A hive's cognition forgets every conversation, and it cannot be undone.
            | "cognition_clear"
            // Every hive's AI engine changes, and readers restart.
            | "set_installation_ai"
            // Every hive's core and installation file move to the motherbee's.
            | "update_installation"
            // A worker's default route and IPv6 change, and its agents' internet with them.
            | "set_hive_egress"
            | "clear_hive_egress"
    )
}

