    #[test]
    fn cloud_actions_catalog_is_the_exposed_registry_subset() {
        let expected_surface: std::collections::HashSet<&str> = [
            "create_tenant",
            "vault_put",
            "run_node",
            "get_ilk",
            "delete_ilk",
            "restore_ilk",
            "delete_tenant",
            "restore_tenant",
            "vault_list",
            "vault_delete",
            "update_tenant",
            "set_ilk_tenant",
            "vault_assign",
            "get_tenant",
            "list_tenants",
            "list_tenant_nodes",
            "get_node_status",
            "start_node",
            "kill_node",
            "get_llm_usage",
        ]
        .into_iter()
        .collect();
        let configured_surface: std::collections::HashSet<&str> =
            IO_CLOUD_EXPOSED_ACTIONS.iter().copied().collect();
        assert_eq!(configured_surface, expected_surface);

        // Every IO.cloud-exposed action must exist in the registry, else a typo would silently
        // drop it from Cloud's discoverable surface (and later from the authz gate).
        let registry: std::collections::HashSet<&str> =
            INTERNAL_ACTION_REGISTRY.iter().map(|s| s.action).collect();
        for action in IO_CLOUD_EXPOSED_ACTIONS {
            assert!(
                registry.contains(action),
                "IO_CLOUD_EXPOSED_ACTIONS lists '{action}' not in INTERNAL_ACTION_REGISTRY"
            );
        }
        // The capability projection returns exactly the exposed set.
        let (status, body) = build_cloud_actions_catalog_response();
        assert_eq!(status, 200);
        let v: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(v["action"], "list_cloud_actions");
        let got: std::collections::HashSet<&str> = v["payload"]["actions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| a["action"].as_str().unwrap())
            .collect();
        assert_eq!(got, expected_surface);
    }

    /// FINDINGS A-197: over the mesh the action catalog is the compact one, each action's name,
    /// description and read_only, and its reply as SY.admin sends it stays within half a mesh
    /// frame. The executor gets it too; the full catalog is HTTP's alone, and asked off HTTP it is
    /// refused, never sent into a frame that refuses it.
    #[tokio::test]
    async fn the_mesh_reads_the_compact_action_catalog_within_half_a_frame() {
        // The view each path names or gets.
        assert_eq!(admin_catalog_view(None, true), Ok(AdminCatalogView::Full));
        assert_eq!(
            admin_catalog_view(Some("compact"), true),
            Ok(AdminCatalogView::Compact)
        );
        assert_eq!(
            admin_catalog_view(None, false),
            Ok(AdminCatalogView::Compact)
        );
        assert_eq!(
            admin_catalog_view(Some(" Compact "), false),
            Ok(AdminCatalogView::Compact)
        );
        assert_eq!(
            admin_catalog_view(Some("full"), false).unwrap_err().0,
            "CATALOG_TOO_LARGE_FOR_MESH"
        );
        assert_eq!(
            admin_catalog_view(Some("summary"), true).unwrap_err().0,
            "INVALID_REQUEST"
        );

        let (ctx, mut harness) = opa_test_admin("admin-catalog-compact");
        let archi = AdminOrigin::Mesh("SY.architect@motherbee");
        let ask = |params: Value, origin: AdminOrigin<'static>| {
            let ctx = &ctx;
            async move {
                dispatch_internal_admin_command(
                    ctx,
                    &ctx.rpc,
                    "list_admin_actions",
                    Some(PRIMARY_HIVE_ID),
                    params,
                    origin,
                )
                .await
                .expect("dispatch")
            }
        };
        // Archi's ask, as it sends it: SY.admin answers it itself.
        let compact = ask(json!({ "view": "compact" }), archi).await;
        assert_eq!(compact.http_status, 200, "{}", compact.envelope);
        assert!(harness
            .next_outgoing_within(Duration::from_millis(100))
            .await
            .is_none());
        let payload = internal_response_payload_value(&compact.envelope);
        assert_eq!(payload["view"], json!("compact"));
        let actions = payload["actions"].as_array().expect("actions");
        assert_eq!(actions.len(), INTERNAL_ACTION_REGISTRY.len());
        for (action, spec) in actions.iter().zip(INTERNAL_ACTION_REGISTRY) {
            let mut fields: Vec<&str> = action
                .as_object()
                .expect("an action")
                .keys()
                .map(String::as_str)
                .collect();
            fields.sort_unstable();
            assert_eq!(fields, vec!["description", "name", "read_only"]);
            assert_eq!(action["name"], json!(spec.action));
            assert_eq!(
                action["read_only"],
                json!(admin_action_is_read_only(spec.action))
            );
        }
        // Without a view the mesh and the executor get the compact one; full is refused off HTTP;
        // HTTP gets the full one by default.
        let default = ask(json!({}), archi).await;
        assert_eq!(
            internal_response_payload_value(&default.envelope)["view"],
            json!("compact")
        );
        let full = ask(json!({ "view": "full" }), archi).await;
        assert_eq!(full.http_status, 413);
        assert_eq!(
            full.envelope["error_code"],
            json!("CATALOG_TOO_LARGE_FOR_MESH")
        );
        let not_a_view = ask(json!({ "view": 1 }), archi).await;
        assert_eq!(not_a_view.envelope["error_code"], json!("INVALID_REQUEST"));
        let executor = ask(json!({}), AdminOrigin::Executor).await;
        assert_eq!(
            internal_response_payload_value(&executor.envelope)["view"],
            json!("compact")
        );
        let refused = ask(json!({ "view": "full" }), AdminOrigin::Executor).await;
        assert_eq!(
            refused.envelope["error_code"],
            json!("CATALOG_TOO_LARGE_FOR_MESH")
        );
        let http = ask(json!({}), AdminOrigin::Http).await;
        let http_payload = internal_response_payload_value(&http.envelope);
        assert_eq!(http_payload["view"], json!("full"));
        assert!(http_payload["actions"][0].get("request_contract").is_some());
        assert!(harness
            .next_outgoing_within(Duration::from_millis(100))
            .await
            .is_none());

        // The reply as SY.admin sends it over the mesh, serialized as its frame: within half the
        // frame's 128 KiB, so the catalog has room to grow.
        let request = Message {
            routing: Routing {
                src: Uuid::new_v4().to_string(),
                src_l2_name: Some("SY.architect@motherbee".to_string()),
                dst: Destination::Unicast(format!("SY.admin@{PRIMARY_HIVE_ID}")),
                ttl: 16,
                trace_id: Uuid::new_v4().to_string(),
            },
            meta: Meta {
                msg_type: "admin".to_string(),
                msg: Some(MSG_ADMIN_COMMAND.to_string()),
                ..Meta::default()
            },
            payload: json!({
                "action": "list_admin_actions",
                "params": { "view": "compact" },
                "request_id": Uuid::new_v4().to_string(),
            }),
        };
        let reply = admin_command_response_message(
            &Uuid::new_v4().to_string(),
            &request,
            "list_admin_actions",
            "ok",
            payload,
            None,
            None,
            Some(Uuid::new_v4().to_string()),
        );
        let frame = serde_json::to_vec(&reply).expect("the reply serializes");
        assert!(
            frame.len() <= 64 * 1024,
            "the compact catalog's reply is {} bytes, past half a mesh frame",
            frame.len()
        );
    }

    /// An `ADMIN_COMMAND` of `action` as a mesh caller sends it.
    fn mesh_admin_request(action: &str, caller: &str) -> Message {
        Message {
            routing: Routing {
                src: Uuid::new_v4().to_string(),
                src_l2_name: Some(caller.to_string()),
                dst: Destination::Unicast(format!("SY.admin@{PRIMARY_HIVE_ID}")),
                ttl: 16,
                trace_id: Uuid::new_v4().to_string(),
            },
            meta: Meta {
                msg_type: "admin".to_string(),
                msg: Some(MSG_ADMIN_COMMAND.to_string()),
                ..Meta::default()
            },
            payload: json!({ "action": action, "params": {}, "request_id": "req-1" }),
        }
    }

    /// FINDINGS A-198: a reply the frame refuses is answered all the same, with REPLY_TOO_LARGE:
    /// its size, the frame's, the action, and how to page it, with how many rows fit.
    #[tokio::test]
    async fn a_mesh_reply_past_the_frame_answers_reply_too_large_with_how_to_page() {
        let (ctx, mut harness) = opa_test_admin("reply-too-large-read");
        let request = mesh_admin_request("list_ilks", "SY.architect@motherbee");
        let ilks: Vec<Value> = (0..400)
            .map(|n| json!({ "ilk_id": format!("ilk:{n:036}"), "display_name": "x".repeat(560) }))
            .collect();
        let payload = json!({ "status": "ok", "count": ilks.len(), "ilks": ilks });
        assert!(mesh_reply::serialized_len(&payload) > mesh_reply::MAX_FRAME_SIZE);
        send_admin_command_response(
            &ctx.rpc,
            &request,
            "list_ilks",
            "ok",
            payload,
            None,
            None,
            Some("req-1".to_string()),
        )
        .await
        .expect("answered");
        let reply = harness
            .next_outgoing_within(Duration::from_secs(1))
            .await
            .expect("a reply");
        assert_eq!(reply.meta.msg.as_deref(), Some(MSG_ADMIN_COMMAND_RESPONSE));
        assert_eq!(reply.payload["status"], json!("error"));
        assert_eq!(reply.payload["error_code"], json!(REPLY_TOO_LARGE));
        assert_eq!(reply.payload["request_id"], json!("req-1"));
        let detail = &reply.payload["error_detail"];
        assert_eq!(detail["action"], json!("list_ilks"));
        assert!(detail["size"].as_u64() > Some(mesh_reply::MAX_FRAME_SIZE as u64));
        assert_eq!(detail["max"], json!(mesh_reply::REPLY_MAX_BYTES));
        assert_eq!(detail["read_only"], json!(true));
        assert!(detail.get("action_ran").is_none());
        assert_eq!(detail["paging"]["params"], json!(["limit", "cursor"]));
        assert_eq!(detail["paging"]["next"], json!("next_cursor"));
        let limit = detail["suggested_limit"].as_u64().expect("how many fit");
        assert!(limit > 0 && limit < 400, "{limit}");
        assert_eq!(detail["outcome"], json!({ "status": "ok" }));
        let message = detail["message"].as_str().expect("message");
        assert!(message.contains("limit and cursor"), "{message}");
        // One reply in the original's place, and a small one.
        assert!(serde_json::to_vec(&reply).expect("frame").len() < 4 * 1024);
        assert!(harness
            .next_outgoing_within(Duration::from_millis(100))
            .await
            .is_none());
        assert_eq!(error_code_to_http_status(REPLY_TOO_LARGE), 413);
    }

    /// FINDINGS A-198: an action that changed something says it ran and keeps its own outcome
    /// (status and ids, and the meta's result), so its caller does not run it again blind.
    #[tokio::test]
    async fn a_write_s_reply_too_large_keeps_its_outcome() {
        let (ctx, mut harness) = opa_test_admin("reply-too-large-write");
        let request = mesh_admin_request("set_node_config", "SY.architect@motherbee");
        let payload = json!({
            "status": "ok",
            "node_name": "AI.sales@worker1",
            "config_version": 4,
            "config": { "prompt": "p".repeat(200_000) },
        });
        send_admin_command_response(
            &ctx.rpc,
            &request,
            "set_node_config",
            "ok",
            payload,
            None,
            None,
            Some("req-1".to_string()),
        )
        .await
        .expect("answered");
        let reply = harness
            .next_outgoing_within(Duration::from_secs(1))
            .await
            .expect("a reply");
        assert_eq!(reply.payload["error_code"], json!(REPLY_TOO_LARGE));
        let detail = &reply.payload["error_detail"];
        assert_eq!(detail["read_only"], json!(false));
        assert_eq!(detail["action_ran"], json!(true));
        assert_eq!(
            detail["outcome"],
            json!({ "status": "ok", "node_name": "AI.sales@worker1" })
        );
        let message = detail["message"].as_str().expect("message");
        assert!(message.contains("set_node_config ran"), "{message}");
        assert!(message.contains("do not run it again"), "{message}");
        assert!(detail.get("http").is_none());
        assert_eq!(
            reply.meta.action_result.map(|result| result.as_str()),
            Some("applied")
        );
        // The mesh-only actions outside the registry that change something say so too.
        for action in ["executor_execute_plan", "externalize", "unexternalize"] {
            assert!(admin_reply_reports_a_change(action), "{action}");
        }
        for action in ["create_tenant", "publish_cloud_endpoint", "delete_ilk"] {
            assert!(!admin_action_is_read_only(action), "{action}");
        }
        assert!(!admin_reply_reports_a_change("list_ilks"));
    }

    /// FINDINGS A-198: the guard measures the reply itself against the frame less the router's
    /// reserve, so a reply the SDK would still send, within its last kilobyte, answers
    /// REPLY_TOO_LARGE too, and that one fits.
    #[tokio::test]
    async fn a_reply_within_the_router_s_reserve_answers_reply_too_large() {
        let (ctx, mut harness) = opa_test_admin("reply-in-the-reserve");
        let request = mesh_admin_request("get_node_config", "SY.architect@motherbee");
        let empty = admin_command_response_message(
            &Uuid::new_v4().to_string(),
            &request,
            "get_node_config",
            "ok",
            json!({ "status": "ok", "config": "" }),
            None,
            None,
            Some("req-1".to_string()),
        );
        // A config that takes the reply to 300 bytes short of the frame: past the reserve.
        let fill = mesh_reply::MAX_FRAME_SIZE - 300 - mesh_reply::serialized_len(&empty);
        let payload = json!({ "status": "ok", "config": "c".repeat(fill) });
        send_admin_command_response(
            &ctx.rpc,
            &request,
            "get_node_config",
            "ok",
            payload,
            None,
            None,
            Some("req-1".to_string()),
        )
        .await
        .expect("answered");
        let reply = harness
            .next_outgoing_within(Duration::from_secs(1))
            .await
            .expect("a reply");
        assert_eq!(reply.payload["error_code"], json!(REPLY_TOO_LARGE));
        let size = reply.payload["error_detail"]["size"]
            .as_u64()
            .expect("size") as usize;
        assert!(
            size > mesh_reply::REPLY_MAX_BYTES && size < mesh_reply::MAX_FRAME_SIZE,
            "{size}"
        );
        assert!(mesh_reply::oversized(&reply).is_none());
    }

    /// FINDINGS A-198 on stage 4's answers: the installation update's refusals (a run under way,
    /// with what it is) and its held answer go over the mesh through the reply guard as they are.
    #[tokio::test]
    async fn the_installation_update_s_answers_go_through_the_reply_guard() {
        let (ctx, mut harness) = opa_test_admin("update-answers-guard");
        let request = mesh_admin_request("get_installation_update", "SY.architect@motherbee");
        let running = installation_update::Running {
            origin: "executor".to_string(),
            since_ms: 1,
            update: Some("upd-1".to_string()),
        };
        let (status, body) = installation_update::run_under_way("update_installation", &running);
        let refusal = parse_internal_response_envelope("update_installation", status, &body);
        let held = json!({
            "update": {
                "id": "upd-1",
                "state": "held",
                "held": ["egress1"],
                "hives": { "egress1": { "core": { "state": "excluded", "exclusion": "rolled_back" } } },
            },
            "open": true,
        });
        for (action, envelope) in [
            ("update_installation", refusal),
            (
                "get_installation_update",
                json!({ "status": "ok", "payload": held, "error_code": null, "error_detail": null }),
            ),
        ] {
            send_admin_command_response(
                &ctx.rpc,
                &request,
                action,
                envelope["status"].as_str().expect("status"),
                internal_response_payload_value(&envelope),
                envelope["error_code"].as_str().map(str::to_string),
                envelope
                    .get("error_detail")
                    .cloned()
                    .filter(|detail| !detail.is_null()),
                Some("req-1".to_string()),
            )
            .await
            .expect("answered");
            let reply = harness
                .next_outgoing_within(Duration::from_secs(1))
                .await
                .expect("a reply");
            assert_eq!(
                reply.payload["error_code"], envelope["error_code"],
                "{action}"
            );
            assert_eq!(reply.payload["payload"], envelope["payload"], "{action}");
        }
    }

    /// FINDINGS A-198: a read without pages names its HTTP route, but never to Fluxbee Cloud's
    /// relay, which reaches SY.admin only through IO.cloud: Cloud is told the pages, or that the
    /// answer has no smaller form.
    #[test]
    fn a_read_s_reply_too_large_names_its_route_but_never_to_cloud() {
        let read = admin_reply_too_large_detail(
            "get_installation_update",
            json!({ "status": "ok" }),
            None,
            200_000,
            mesh_reply::REPLY_MAX_BYTES,
            AdminReplyHint::PagesOrHttp,
        );
        assert_eq!(read["read_only"], json!(true));
        assert!(read.get("action_ran").is_none());
        assert!(read.get("paging").is_none());
        assert_eq!(read["http"], json!("GET /installation/update"));

        assert_eq!(
            admin_reply_hint_reach("IO.cloud@motherbee"),
            AdminReplyHint::PagesOnly
        );
        assert_eq!(
            admin_reply_hint_reach("SY.architect@motherbee"),
            AdminReplyHint::PagesOrHttp
        );
        let cloud_read = admin_reply_too_large_detail(
            "get_tenant",
            json!({ "status": "ok", "tenant_id": "tnt:a" }),
            None,
            200_000,
            mesh_reply::REPLY_MAX_BYTES,
            AdminReplyHint::PagesOnly,
        );
        assert!(cloud_read.get("http").is_none(), "{cloud_read}");
        let message = cloud_read["message"].as_str().expect("message");
        assert!(!message.contains("HTTP"), "{message}");
        let cloud_list = admin_reply_too_large_detail(
            "list_tenant_nodes",
            json!({ "status": "ok", "tenant_id": "tnt:a" }),
            Some(800),
            300_000,
            mesh_reply::REPLY_MAX_BYTES,
            AdminReplyHint::PagesOnly,
        );
        assert_eq!(cloud_list["paging"]["params"], json!(["limit", "cursor"]));
        assert!(cloud_list["suggested_limit"].as_u64() > Some(0));
        assert!(cloud_list.get("http").is_none());
    }

    /// FINDINGS A-198: a REPLY_TOO_LARGE from the node behind SY.admin (its answer did not fit its
    /// hop) reaches the caller in SY.admin's own shape: the action's pages, how many rows fit, the
    /// outcome, never the HTTP route, which takes the same hop; a write's says it ran, and the
    /// meta's result is the action's own.
    #[test]
    fn a_source_s_reply_too_large_takes_sy_admin_s_shape() {
        let source = mesh_reply::reply_too_large_payload(
            "TNT_LIST",
            300_000,
            mesh_reply::REPLY_MAX_BYTES,
            json!({ "status": "ok" }),
            Some(900),
            "ask it in pages with limit and cursor, following next_cursor",
        );
        let (status, body) = build_admin_http_response("list_tenants", Ok(source));
        assert_eq!(status, 413);
        let envelope: Value = serde_json::from_str(&body).expect("envelope");
        assert_eq!(envelope["error_code"], json!(REPLY_TOO_LARGE));
        assert_eq!(envelope["payload"], Value::Null);
        let detail = &envelope["error_detail"];
        assert_eq!(detail["action"], json!("list_tenants"));
        assert_eq!(detail["paging"]["params"], json!(["limit", "cursor"]));
        let limit = detail["suggested_limit"].as_u64().expect("how many fit");
        assert!(limit > 0 && limit < 900, "{limit}");
        assert!(detail.get("http").is_none());
        assert!(detail["source"]
            .as_str()
            .is_some_and(|text| text.contains("TNT_LIST")));

        let write = mesh_reply::reply_too_large_payload(
            "set_node_config",
            200_000,
            mesh_reply::REPLY_MAX_BYTES,
            json!({ "status": "ok", "node_name": "AI.sales@worker1" }),
            None,
            "it has no smaller form over the mesh",
        );
        let (_, body) = build_admin_http_response("set_node_config", Ok(write));
        let envelope: Value = serde_json::from_str(&body).expect("envelope");
        let detail = &envelope["error_detail"];
        assert_eq!(detail["action_ran"], json!(true));
        assert_eq!(
            detail["outcome"],
            json!({ "status": "ok", "node_name": "AI.sales@worker1" })
        );
        assert!(detail.get("http").is_none());
        let request = mesh_admin_request("set_node_config", "SY.architect@motherbee");
        let reply = admin_command_response_message(
            &Uuid::new_v4().to_string(),
            &request,
            "set_node_config",
            "error",
            Value::Null,
            Some(REPLY_TOO_LARGE.to_string()),
            Some(detail.clone()),
            None,
        );
        assert_eq!(
            reply.meta.action_result.map(|result| result.as_str()),
            Some("applied")
        );
    }

