    /// FINDINGS A-198: SY.admin asks SY.identity in pages and assembles them: every ILK without a
    /// limit, as before, and with one at most that many, with SY.identity's next_cursor.
    #[tokio::test]
    async fn sy_admin_assembles_the_identity_pages() {
        let (ctx, mut harness) = opa_test_admin("identity-pages");
        let wait = Duration::from_secs(5);
        let whole = handle_identity_query(
            &ctx,
            &ctx.rpc,
            "list_ilks",
            json!({ "include_deleted": true }),
            None,
        );
        let drive = async {
            let first = harness.next_outgoing_within(wait).await.expect("page 1");
            assert_eq!(first.meta.msg.as_deref(), Some("ILK_LIST"));
            assert_eq!(first.payload["include_deleted"], json!(true));
            assert_eq!(first.payload["limit"], json!(LIST_SOURCE_PAGE_ROWS));
            assert!(first.payload.get("cursor").is_none());
            let page = json!({
                "status": "ok", "count": 2, "total": 3, "next_cursor": "ilk:b",
                "ilks": [{ "ilk_id": "ilk:a" }, { "ilk_id": "ilk:b" }],
            });
            harness
                .inject(reply_to(&first, "ILK_LIST_RESPONSE", page))
                .await
                .unwrap();
            let second = harness.next_outgoing_within(wait).await.expect("page 2");
            assert_eq!(second.payload["cursor"], json!("ilk:b"));
            let page = json!({
                "status": "ok", "count": 1, "total": 3, "ilks": [{ "ilk_id": "ilk:c" }],
            });
            harness
                .inject(reply_to(&second, "ILK_LIST_RESPONSE", page))
                .await
                .unwrap();
        };
        let (answer, ()) = tokio::join!(whole, drive);
        let (status, body) = answer.expect("answered");
        assert_eq!(status, 200, "{body}");
        let body: Value = serde_json::from_str(&body).expect("body");
        let ilks: Vec<&str> = body["payload"]["ilks"]
            .as_array()
            .expect("ilks")
            .iter()
            .filter_map(|ilk| ilk["ilk_id"].as_str())
            .collect();
        assert_eq!(ilks, vec!["ilk:a", "ilk:b", "ilk:c"]);
        assert_eq!(body["payload"]["count"], json!(3));
        assert_eq!(body["payload"]["total"], json!(3));
        assert!(body["payload"].get("next_cursor").is_none());

        // With a limit, one page of that many, and where the next one starts.
        let paged = handle_identity_query(
            &ctx,
            &ctx.rpc,
            "list_tenants",
            json!({ "limit": "2" }),
            None,
        );
        let drive = async {
            let first = harness.next_outgoing_within(wait).await.expect("page 1");
            assert_eq!(first.meta.msg.as_deref(), Some("TNT_LIST"));
            assert_eq!(first.payload["limit"], json!(2));
            let page = json!({
                "status": "ok", "count": 2, "total": 5, "next_cursor": "tnt:b",
                "tenants": [{ "tenant_id": "tnt:a" }, { "tenant_id": "tnt:b" }],
            });
            harness
                .inject(reply_to(&first, "TNT_LIST_RESPONSE", page))
                .await
                .unwrap();
        };
        let (answer, ()) = tokio::join!(paged, drive);
        let (_, body) = answer.expect("answered");
        let body: Value = serde_json::from_str(&body).expect("body");
        assert_eq!(body["payload"]["count"], json!(2));
        assert_eq!(body["payload"]["next_cursor"], json!("tnt:b"));
        assert!(harness
            .next_outgoing_within(Duration::from_millis(100))
            .await
            .is_none());
        // A limit that is no number of rows is refused before anything is asked.
        let (status, _) =
            handle_identity_query(&ctx, &ctx.rpc, "list_ilks", json!({ "limit": 0 }), None)
                .await
                .expect("answered");
        assert_eq!(status, 400);
    }

    /// FINDINGS A-198: SY.admin's own vault checks see every secret, page after page: the provider
    /// keys a reader may read and the secrets that block a tenant's purge, past SY.vault's first
    /// page.
    #[tokio::test]
    async fn sy_admin_s_vault_checks_read_every_page() {
        let (ctx, mut harness) = opa_test_admin("vault-check-pages");
        let wait = Duration::from_secs(5);
        let secret = |key: &str, ilk: &str| json!({ "key": key, "metadata": { "ilk": ilk, "assigned_ilks": [] } });
        let keys = list_provider_keys(&ctx.rpc, "motherbee", "tnt:x", AiProvider::Anthropic);
        let drive = async {
            let first = harness.next_outgoing_within(wait).await.expect("page 1");
            assert_eq!(first.meta.msg.as_deref(), Some(MSG_VAULT_LIST));
            assert_eq!(first.payload["filter"]["tenant_id"], json!("tnt:x"));
            assert_eq!(
                first.payload["filter"]["limit"],
                json!(LIST_SOURCE_PAGE_ROWS)
            );
            assert!(first.payload.get("cursor").is_none());
            let page = json!({
                "status": "ok", "count": 1, "total": 2, "next_cursor": "0a",
                "secrets": [secret("anthropic_a", "ilk:a")],
            });
            harness
                .inject(reply_to(&first, MSG_VAULT_LIST_RESPONSE, page))
                .await
                .unwrap();
            let second = harness.next_outgoing_within(wait).await.expect("page 2");
            assert_eq!(second.payload["cursor"], json!("0a"));
            let page = json!({
                "status": "ok", "count": 1, "total": 2,
                "secrets": [secret("anthropic_b", "ilk:b")],
            });
            harness
                .inject(reply_to(&second, MSG_VAULT_LIST_RESPONSE, page))
                .await
                .unwrap();
        };
        let (keys, ()) = tokio::join!(keys, drive);
        let keys = keys.expect("listed");
        assert_eq!(keys.len(), 2);
        assert!(keys.iter().any(|key| key.read_by(Some("ilk:b"))));

        let purge = json!({ "tenant_id": "tnt:x" });
        let block = purge_tenant_vault_block(&ctx.rpc, "motherbee", &purge);
        let drive = async {
            let first = harness.next_outgoing_within(wait).await.expect("page 1");
            let page = json!({
                "status": "ok", "count": 1, "total": 2, "next_cursor": "0a",
                "secrets": [secret("slack_a", "ilk:a")],
            });
            harness
                .inject(reply_to(&first, MSG_VAULT_LIST_RESPONSE, page))
                .await
                .unwrap();
            let second = harness.next_outgoing_within(wait).await.expect("page 2");
            let page = json!({
                "status": "ok", "count": 1, "total": 2, "secrets": [secret("slack_b", "ilk:b")],
            });
            harness
                .inject(reply_to(&second, MSG_VAULT_LIST_RESPONSE, page))
                .await
                .unwrap();
        };
        let (block, ()) = tokio::join!(block, drive);
        let (status, body) = block.expect("blocked");
        assert_eq!(status, 409);
        assert!(
            body.contains("2 secret(s)") && body.contains("slack_b"),
            "{body}"
        );

        // A listing SY.vault refuses blocks the purge too: it fails closed.
        let block = purge_tenant_vault_block(&ctx.rpc, "motherbee", &purge);
        let drive = async {
            let first = harness.next_outgoing_within(wait).await.expect("listing");
            let refusal =
                json!({ "status": "error", "error_code": "UNAUTHORIZED", "message": "no" });
            harness
                .inject(reply_to(&first, MSG_VAULT_LIST_RESPONSE, refusal))
                .await
                .unwrap();
        };
        let (block, ()) = tokio::join!(block, drive);
        let (_, body) = block.expect("blocked");
        assert!(body.contains("VAULT_CHECK_FAILED"), "{body}");
    }

