    /// FINDINGS A-198: an assembled listing takes at most its caller's own time: each page is
    /// asked with the time left, and one not done by then answers TIMEOUT.
    #[tokio::test]
    async fn a_listing_past_its_deadline_answers_timeout() {
        let asked = std::sync::atomic::AtomicUsize::new(0);
        let within = Duration::from_millis(80);
        let listing = assemble_list_pages("nodes", &PageAsk::default(), within, |_, left| {
            let page = asked.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            async move {
                assert!(left <= within);
                tokio::time::sleep(Duration::from_millis(30)).await;
                Ok(json!({
                    "status": "ok",
                    "nodes": [{ "name": format!("n{page}") }],
                    "next_cursor": format!("motherbee|n{page}"),
                }))
            }
        })
        .await;
        let err = listing.expect_err("past its deadline");
        assert_eq!(infer_transport_error_code(&err.to_string()), "TIMEOUT");
        let pages = asked.load(std::sync::atomic::Ordering::SeqCst);
        assert!((2..=4).contains(&pages), "{pages} pages");
    }

    /// FINDINGS A-198: `list_versions`' pages each compare their hives with the motherbee's
    /// snapshot; joined, the hives' verdicts add up and the worst one wins.
    #[test]
    fn the_versions_pages_comparisons_join() {
        let page = |verdict: &str, hives: Value| json!({ "reference_hive": "motherbee", "verdict": verdict, "hives": hives });
        let merged = merge_versions_comparisons(&[
            page(
                "match",
                json!([{ "hive_id": "worker1", "verdict": "match" }]),
            ),
            page(
                "differs",
                json!([{ "hive_id": "worker2", "verdict": "differs" }]),
            ),
        ]);
        assert_eq!(merged["verdict"], json!("differs"));
        assert_eq!(merged["reference_hive"], json!("motherbee"));
        assert_eq!(merged["hives"].as_array().map(Vec::len), Some(2));
        let merged = merge_versions_comparisons(&[
            page("match", json!([])),
            page(
                "unknown",
                json!([{ "hive_id": "worker3", "verdict": "unknown" }]),
            ),
        ]);
        assert_eq!(merged["verdict"], json!("unknown"));
        let merged =
            merge_versions_comparisons(&[page("match", json!([])), page("match", json!([]))]);
        assert_eq!(merged["verdict"], json!("match"));
    }

    #[test]
    fn externalize_authz_gate_io_prefix_and_ownership() {
        let owner = "IO.cloud@motherbee";
        // Trusted internal path (no router-stamped origin) is always allowed.
        assert!(authorize_channel_command(None, owner).is_ok());
        // The owner externalizing its own channel is allowed (I1 + I8).
        assert!(authorize_channel_command(Some("IO.cloud@motherbee"), owner).is_ok());
        // A non-IO node is rejected (I1) even if the name matched some owner.
        assert!(authorize_channel_command(Some("SY.admin@motherbee"), owner).is_err());
        assert!(authorize_channel_command(Some("AI.sales@motherbee"), owner).is_err());
        // An IO node may NOT externalize someone else's channel (I8).
        assert!(authorize_channel_command(Some("IO.other@motherbee"), owner).is_err());
        // Same node name, different hive is still a different node — rejected (I8, exact match).
        assert!(authorize_channel_command(Some("IO.cloud@worker1"), owner).is_err());
    }

