    /// Only the primary, SY.admin's own hive, writes an ILK or a tenant (A-143, WF Case 5's gate:
    /// Archi assigned a worker's agents their roles with `hive: worker1`), and a spoke's replica
    /// takes no request from SY.admin of another hive, reads included (2026-11-07: on 8.x
    /// `GET /hives/worker1/identity/ilks` answered UNAUTHORIZED_REGISTRAR from the replica). So a
    /// read that names a spoke asks the primary, and answers what it says.
    #[tokio::test]
    async fn a_read_of_a_spokes_identities_asks_the_primary() {
        let (ctx, mut harness) = opa_test_admin("identity-read-primary");
        let no_query = HashMap::new();
        let ilk = format!("ilk:{}", Uuid::new_v4());
        let tenant = format!("tnt:{}", Uuid::new_v4());
        for (path, request, response) in [
            (
                "/hives/worker1/identity/ilks".to_string(),
                "ILK_LIST",
                "ILK_LIST_RESPONSE",
            ),
            (
                "/hives/worker1/identity/tenants".to_string(),
                "TNT_LIST",
                "TNT_LIST_RESPONSE",
            ),
            (
                format!("/hives/worker1/identity/ilks/{ilk}"),
                "ILK_GET",
                "ILK_GET_RESPONSE",
            ),
            (
                format!("/hives/worker1/identity/tenants/{tenant}"),
                "TNT_GET",
                "TNT_GET_RESPONSE",
            ),
        ] {
            let answered = async {
                let sent = harness
                    .next_outgoing_within(Duration::from_secs(5))
                    .await
                    .expect(request);
                harness
                    .inject(reply_to(&sent, response, json!({ "status": "ok" })))
                    .await
                    .unwrap();
                sent
            };
            let (served, sent) = tokio::join!(
                handle_hive_paths("GET", &path, &no_query, &[], &ctx, &ctx.rpc),
                answered
            );
            assert_eq!(sent.meta.msg.as_deref(), Some(request), "{path}");
            assert_eq!(dst_of(&sent), json!("SY.identity@motherbee"), "{path}");
            let (status, body) = served.expect("route").expect("served");
            assert_eq!(status, 200, "{path}: {body}");
        }
    }

    /// The direct dispatch routes every action the executor may run, a workflow's deploy included
    /// (WF Case 5's gate: it went through `handle_admin_command_with_origin`, which answered
    /// `UNKNOWN_ACTION` for `wf_rules_compile_apply`). The step reaches SY.wf-rules as the plan
    /// wrote it, and its answer is the step's result.
    #[tokio::test]
    async fn a_fixed_workflow_deploy_step_reaches_wf_rules_as_planned() {
        let (ctx, mut harness) = opa_test_admin("executor-direct-wf");
        let step = AdminExecutorPlanStep {
            id: "s1".to_string(),
            action: "wf_rules_compile_apply".to_string(),
            args: json!({
                "hive": "worker1",
                "workflow_name": "invoice",
                "definition": wf_rules_example_definition(),
                "auto_spawn": true,
                "tenant_id": "tnt:77f601f7-c045-44dc-bb97-5aab22b067a4",
            }),
            executor_fill: None,
        };
        let client = Arc::clone(&ctx.rpc);
        let dispatch = execute_admin_executor_step_fallback(
            &ctx,
            &client,
            "run-1",
            0,
            &step,
            ExecutorDirectDispatch::AsPlanned,
        );
        let wf_rules = async {
            let sent = harness
                .next_outgoing_within(Duration::from_secs(5))
                .await
                .expect("the deploy");
            assert_eq!(sent.meta.msg.as_deref(), Some("CONFIG_SET"));
            assert_eq!(dst_of(&sent), json!("SY.wf-rules@worker1"));
            let config = &sent.payload["config"];
            assert_eq!(config["operation"], json!("compile_apply"));
            assert_eq!(config["definition"], wf_rules_example_definition());
            assert_eq!(config["auto_spawn"], json!(true));
            harness
                .inject(reply_to(
                    &sent,
                    "CONFIG_RESPONSE",
                    json!({
                        "ok": true,
                        "node_name": "SY.wf-rules@worker1",
                        "state": "configured",
                        "config_version": 1,
                        "wf_node": { "node_name": "WF.invoice@worker1", "action": "restarted", "status": "ok" },
                    }),
                ))
                .await
                .unwrap();
        };
        let ((event, failure), ()) = tokio::join!(dispatch, wf_rules);
        assert!(failure.is_none(), "{failure:?}");
        assert_eq!(event.status, "done");
        assert_eq!(event.summary, "wf_rules_compile_apply -> done (as planned)");
        let answer = event.result_preview.expect("the step's answer");
        assert_eq!(answer["status"], json!("ok"), "{answer}");
        assert_eq!(
            answer["payload"]["wf_node"]["status"],
            json!("ok"),
            "{answer}"
        );
    }

    /// A step the plan left nothing to fill is dispatched as planned, without the model; one with
    /// fields to fill still goes to the model (WF Case 5's gate: a workflow's definition outgrew
    /// the model's answer when it had to repeat it).
    #[test]
    fn a_step_with_nothing_to_fill_skips_the_executor_model() {
        let step = |executor_fill: Option<AdminExecutorFill>| AdminExecutorPlanStep {
            id: "s1".to_string(),
            action: "wf_rules_compile_apply".to_string(),
            args: serde_json::json!({ "hive": "worker1", "workflow_name": "sales" }),
            executor_fill,
        };
        assert!(executor_step_has_nothing_to_fill(&step(None)));
        assert!(executor_step_has_nothing_to_fill(&step(Some(
            AdminExecutorFill::default()
        ))));
        assert!(!executor_step_has_nothing_to_fill(&step(Some(
            AdminExecutorFill {
                allowed: vec!["version".to_string()],
                notes: vec![],
            }
        ))));
        assert_eq!(ExecutorDirectDispatch::AsPlanned.label(), "as planned");
        assert_eq!(
            ExecutorDirectDispatch::ModelDidNotCall.invalid_code(),
            "EXECUTOR_NO_ACTION_CALL"
        );
    }

