    /// The plan Archi stages to take a page down (A-120): one step, naming the page by its id or
    /// by its link's key, and nothing else, a hive included.
    #[test]
    fn an_executor_plan_takes_a_page_down_by_its_id_or_its_links_key() {
        let plan = |args: Value| {
            parse_executor_plan(json!({
                "plan_version": ADMIN_EXECUTOR_PLAN_VERSION,
                "kind": ADMIN_EXECUTOR_PLAN_KIND,
                "metadata": { "name": "take_page_down", "target_hive": PRIMARY_HIVE_ID },
                "execution": {
                    "strict": true,
                    "stop_on_error": true,
                    "allow_help_lookup": true,
                    "steps": [{ "id": "s1", "action": "unpublish_artifact", "args": args }]
                }
            }))
        };
        let publication_id = format!("pub:{}", Uuid::new_v4());
        let key = mint_public_capability();
        for args in [
            json!({ "publication_id": publication_id }),
            json!({ "key": key }),
        ] {
            assert!(plan(args.clone()).is_ok(), "{args}");
        }
        let refused = plan(json!({ "key": key, "hive": PRIMARY_HIVE_ID }))
            .expect_err("unpublish_artifact takes no hive");
        assert!(refused.contains("unexpected field 'hive'"), "{refused}");
        let spaced = parse_executor_plan(json!({
            "plan_version": ADMIN_EXECUTOR_PLAN_VERSION,
            "kind": ADMIN_EXECUTOR_PLAN_KIND,
            "metadata": { "name": "take_page_down", "target_hive": PRIMARY_HIVE_ID },
            "execution": {
                "strict": true,
                "stop_on_error": true,
                "allow_help_lookup": true,
                "steps": [{ "id": "s1", "action": " unpublish_artifact", "args": { "key": key } }]
            }
        }))
        .expect_err("a step names its action with no surrounding whitespace");
        assert!(spaced.contains("no surrounding whitespace"), "{spaced}");
        // Its run log would keep the key only as its hash all the same.
        let logged = executor_log_step_args(" unpublish_artifact", &json!({ "key": key }));
        assert!(
            logged.get("key_sha256").is_some() && logged.get("key").is_none(),
            "{logged}"
        );
    }

    #[test]
    fn public_artifact_policy_is_fixed_by_mime_and_presentation() {
        let html = BlobRef {
            ref_type: "blob_ref".to_string(),
            blob_name: "report_0123456789abcdef.html".to_string(),
            size: 42,
            mime: "text/html".to_string(),
            filename_original: "report.html".to_string(),
            spool_day: "2026-07-17".to_string(),
        };
        assert_eq!(
            normalize_public_presentation(&html, Some("inline")).unwrap(),
            (
                "text/html; charset=utf-8".to_string(),
                "inline".to_string(),
                "sandboxed-html-v1".to_string()
            )
        );
        assert_eq!(
            normalize_public_presentation(&html, Some("attachment"))
                .unwrap()
                .1,
            "attachment"
        );
        assert!(normalize_public_presentation(&html, Some("raw-headers")).is_err());
    }

    /// H4.3 — Admin's executor hot-refresh filters incoming
    /// `VAULT_SECRET_CHANGED` events by `(resource_type=openai, tenant=root,
    /// ilk=self)`. Asserts the same `VaultSecretInterest` semantics the
    /// `handle_vault_secret_changed_admin` handler relies on.
    #[test]
    fn admin_vault_interest_filters_openai_at_root_tenant() {
        use fluxbee_sdk::protocol::{VaultSecretChangedPayload, VaultSecretOp};
        let self_ilk = "ilk:test-admin";
        let interest = VaultSecretInterest {
            resource_type: "openai",
            my_tenant: fluxbee_sdk::DEFAULT_ROOT_TENANT_ID,
            my_ilk: Some(self_ilk),
            system_caller: true,
        };

        let matches = VaultSecretChangedPayload {
            op: VaultSecretOp::Put,
            resource_type: "openai".to_string(),
            tenant_id: fluxbee_sdk::DEFAULT_ROOT_TENANT_ID.to_string(),
            ilk: None,
            assigned_ilks: Vec::new(),
            general: true,
            version: 1,
            key: "secret/openai".to_string(),
            hive_id: "motherbee".to_string(),
            at_ms: 0,
        };
        assert!(matches.matches_interest(&interest));

        let wrong_resource = VaultSecretChangedPayload {
            resource_type: "postgres".to_string(),
            ..matches.clone()
        };
        assert!(!wrong_resource.matches_interest(&interest));

        let wrong_tenant = VaultSecretChangedPayload {
            tenant_id: "tnt:other".to_string(),
            ..matches.clone()
        };
        assert!(!wrong_tenant.matches_interest(&interest));
    }

    /// The admin API never writes SY.admin's ACME accounts, nor reads their value
    /// (docs/acme-edge-certificates-v1.md §3):
    /// the operator, the executor, Archi and Cloud all reach SY.vault through
    /// `handle_vault_command`, which refuses before anything is sent.
    #[tokio::test]
    async fn the_admin_api_refuses_writes_to_acme_accounts() {
        let (ctx, mut harness) = opa_test_admin("acme-account-writes");
        let key = acme::account_vault_key(acme::LETS_ENCRYPT_DIRECTORY);
        for (action, payload) in [
            (
                "vault_put",
                json!({"key": key, "value": {"id": "x"}, "metadata": {"resource_type": "acme_account"}}),
            ),
            ("vault_rotate", json!({"key": key, "value": {"id": "x"}})),
            ("vault_rollback", json!({"key": key})),
            ("vault_delete", json!({"key": key.to_uppercase()})),
            (
                "vault_assign",
                json!({"key": key, "assigned_nodes": ["SY.architect@motherbee"]}),
            ),
        ] {
            let (status, body) = handle_vault_command(&ctx, &ctx.rpc, action, payload, None)
                .await
                .expect("answered");
            let body: Value = serde_json::from_str(&body).unwrap();
            assert_eq!(status, 403, "{action}: {body}");
            assert_eq!(body["error_code"], "RESERVED_KEY", "{action}");
        }
        // Over the mesh, as Archi or Cloud would ask.
        for caller in ["SY.architect@motherbee", "IO.cloud@motherbee"] {
            let refused = dispatch_internal_admin_command(
                &ctx,
                &ctx.rpc,
                "vault_put",
                Some("motherbee"),
                json!({"key": key, "value": {"id": "x"}, "metadata": {"resource_type": "acme_account", "tenant_id": fluxbee_sdk::DEFAULT_ROOT_TENANT_ID}}),
                AdminOrigin::Mesh(caller),
            )
            .await
            .expect("answered");
            assert_eq!(refused.http_status, 403, "{caller}: {}", refused.envelope);
        }
        assert!(
            harness
                .next_outgoing_within(Duration::from_millis(50))
                .await
                .is_none(),
            "nothing reached SY.vault"
        );
        // Nor is its value read; its metadata is.
        let (status, body) =
            handle_vault_command(&ctx, &ctx.rpc, "vault_get", json!({"key": key}), None)
                .await
                .expect("answered");
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 403, "{body}");
        assert_eq!(body["error_code"], "RESERVED_KEY");
        assert!(refuse_acme_account_access("vault_get_metadata", &json!({"key": key})).is_none());
        // Other keys are not reserved here.
        assert!(refuse_acme_account_access("vault_put", &json!({"key": "edge_tls"})).is_none());
        assert!(refuse_acme_account_access("vault_get", &json!({"key": "edge_tls"})).is_none());
    }

    /// The four ACME actions are in the catalog with their routes, read-only and confirmation
    /// flags (docs/acme-edge-certificates-v1.md §7).
    #[test]
    fn the_acme_actions_are_registered_with_their_contracts() {
        for (action, route, read_only, confirm) in [
            ("acme_status", "GET /acme/status", true, false),
            ("acme_renew", "POST /acme/renew", false, true),
            ("acme_test", "POST /acme/test", false, true),
            ("acme_reload", "POST /acme/reload", false, false),
        ] {
            let spec = resolve_internal_action_spec(action).expect(action);
            assert!(matches!(spec.route, InternalActionRoute::Acme));
            let doc = build_admin_action_doc(spec);
            assert_eq!(doc["read_only"], read_only, "{action}");
            assert_eq!(doc["confirmation_required"], confirm, "{action}");
            assert_eq!(doc["path_patterns"], json!([route]), "{action}");
            assert_ne!(doc["summary"], "Admin action.", "{action}");
            assert!(!admin_action_request_notes(action).is_empty(), "{action}");
            assert!(admin_action_example_scmd(action).is_some(), "{action}");
            let (method, path) = route.split_once(' ').unwrap();
            assert_eq!(admin_methods_allowed_for_path(path), vec![method]);
        }
        assert_eq!(admin_action_timeout("acme_reload"), Duration::from_secs(90));
    }

    #[tokio::test]
    async fn the_acme_actions_take_no_parameters() {
        let (ctx, _harness) = opa_test_admin("acme-params");
        for action in ["acme_status", "acme_renew", "acme_test", "acme_reload"] {
            let (status, body) =
                handle_acme_action(&ctx, action, &json!({"directory_url": "https://x"})).await;
            let body: Value = serde_json::from_str(&body).unwrap();
            assert_eq!(status, 400, "{action}");
            assert_eq!(body["error_code"], "INVALID_REQUEST");
        }
        // Without an acme section: the status answers, renew and test say why they cannot run.
        let (status, body) = handle_acme_action(&ctx, "acme_status", &json!({})).await;
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 200);
        assert_eq!(body["payload"]["config"]["state"], "absent");
        let (status, body) = handle_acme_action(&ctx, "acme_renew", &json!({})).await;
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 409);
        assert_eq!(body["error_code"], "ACME_OFF");
        assert_eq!(acme_http_body(b""), json!({}));
        assert_eq!(acme_http_body(b"{}"), json!({}));
        assert!(!acme_http_body(b"not json").is_object());
    }

    /// An admin wired to the test dispatcher whose registry holds worker1 (a worker) and ingress1
    /// (an ingress), both joined.
    fn mesh_test_admin(prefix: &str) -> (AdminContext, fluxbee_sdk::RouterDispatcherTestHarness) {
        let (ctx, harness) = opa_test_admin(prefix);
        let registry = hive_registry(&ctx);
        for (hive, role) in [("worker1", "worker"), ("ingress1", "ingress")] {
            write_registry_entry(
                registry.root(),
                hive,
                &format!(
                    "hive_id: {hive}\nstatus: connected\nrole: {role}\njoin:\n  phase: done\n"
                ),
            );
        }
        (ctx, harness)
    }

    /// The table runs first in the mesh dispatch: a refused caller gets 403 UNAUTHORIZED and
    /// nothing is sent. The executor and the HTTP API are not mesh callers.
    #[tokio::test]
    async fn a_refused_mesh_caller_gets_unauthorized_and_nothing_is_sent() {
        let (ctx, mut harness) = mesh_test_admin("mesh-refusals");
        for (caller, action, params) in [
            // The calls a teardown made before teardown_node.
            (
                "SY.orchestrator@worker1",
                "delete_ilk",
                json!({ "ilk_id": TEST_ILK }),
            ),
            (
                "SY.orchestrator@worker1",
                "vault_list",
                json!({ "filter": { "ilk": TEST_ILK } }),
            ),
            ("", "vault_get", json!({ "key": "edge_tls" })),
            (
                "IO.api.sales@ingress1",
                "externalize",
                json!({ "ich": "ich:x" }),
            ),
            (
                "SY.orchestrator@ingress1",
                "teardown_node",
                teardown_params("IO.x@ingress1"),
            ),
            (
                "SY.wf-rules@joining1",
                "run_node",
                json!({ "node_name": "WF.invoice@joining1", "runtime": "wf.invoice" }),
            ),
            (
                "IO.cloud@motherbee",
                "add_hive",
                json!({ "hive_id": "worker9" }),
            ),
            ("WF.invoice@worker1", "executor_execute_plan", json!({})),
        ] {
            let refused = dispatch_internal_admin_command(
                &ctx,
                &ctx.rpc,
                action,
                Some(PRIMARY_HIVE_ID),
                params,
                AdminOrigin::Mesh(caller),
            )
            .await
            .expect("answered");
            assert_eq!(refused.http_status, 403, "{caller} {action}");
            assert_eq!(refused.envelope["error_code"], json!("UNAUTHORIZED"));
        }
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());

        // The executor runs a step of a plan already approved: it reaches SY.vault.
        let step = dispatch_internal_admin_command(
            &ctx,
            &ctx.rpc,
            "vault_list",
            Some(PRIMARY_HIVE_ID),
            json!({ "filter": { "ilk": TEST_ILK } }),
            AdminOrigin::Executor,
        );
        let drive = async {
            let sent = harness
                .next_outgoing_within(Duration::from_secs(5))
                .await
                .expect("the vault list");
            assert_eq!(sent.meta.msg.as_deref(), Some(MSG_VAULT_LIST));
            let done = reply_to(
                &sent,
                MSG_VAULT_LIST_RESPONSE,
                json!({ "status": "ok", "secrets": [] }),
            );
            harness.inject(done).await.unwrap();
        };
        let (result, ()) = tokio::join!(step, drive);
        assert_eq!(result.expect("dispatch").http_status, 200);
    }

    /// SY.wf-rules@H publishes wf.<x> only while no WF.<x> is connected on another hive, which
    /// SY.admin reads from shared memory without asking anyone. Regions that cannot be read answer
    /// a retryable 503, never a refusal of the caller.
    #[tokio::test]
    async fn a_wf_rules_package_reads_the_connected_nodes_from_shared_memory() {
        let (mut ctx, mut harness) = mesh_test_admin("mesh-wf-package");
        let params = workflow_package(workflow_package_json(
            "wf.invoice",
            "workflow",
            Some("wf.engine"),
        ));
        let caller = AdminOrigin::Mesh("SY.wf-rules@worker1");

        let held = dispatch_internal_admin_command(
            &ctx,
            &ctx.rpc,
            "publish_runtime_package",
            None,
            params.clone(),
            caller,
        )
        .await
        .expect("dispatch");
        assert_eq!(held.http_status, 503, "{}", held.envelope);
        assert_eq!(held.envelope["error_code"], json!("INVENTORY_UNAVAILABLE"));
        assert_eq!(error_code_to_http_status("INVENTORY_UNAVAILABLE"), 503);

        ctx.connected_nodes = Arc::new(|_| {
            Ok(connected_now(
                &["worker1", "worker2"],
                &["WF.invoice@worker1", "WF.invoice@worker2"],
            ))
        });
        let refused = dispatch_internal_admin_command(
            &ctx,
            &ctx.rpc,
            "publish_runtime_package",
            None,
            params.clone(),
            caller,
        )
        .await
        .expect("dispatch");
        assert_eq!(refused.http_status, 403, "{}", refused.envelope);
        assert_eq!(refused.envelope["error_code"], json!("UNAUTHORIZED"));

        ctx.connected_nodes = Arc::new(|_| {
            Ok(connected_now(
                &["worker1", "worker2"],
                &["WF.invoice@worker1", "WF.billing@worker2"],
            ))
        });
        // Admitted: the publisher answers for itself (the tests have no runtime manifest).
        let admitted = dispatch_internal_admin_command(
            &ctx,
            &ctx.rpc,
            "publish_runtime_package",
            None,
            params,
            caller,
        )
        .await
        .expect("dispatch");
        for code in ["UNAUTHORIZED", "INVENTORY_UNAVAILABLE"] {
            assert_ne!(
                admitted.envelope["error_code"],
                json!(code),
                "{}",
                admitted.envelope
            );
        }
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

    /// SY.wf-rules sends only its own fields: a `test_hold_ms` (which holds the manifest lock every
    /// publish and deploy waits for), a follow-up or a bundle is refused. Archi is not held to it.
    #[test]
    fn wf_rules_sends_only_the_fields_of_its_deploys() {
        let caller = "SY.wf-rules@worker1";
        let package = || {
            workflow_package(workflow_package_json(
                "wf.invoice",
                "workflow",
                Some("wf.engine"),
            ))
        };
        let remove = json!({ "runtime": "wf.invoice", "runtime_version": "0.0.2" });
        assert!(mesh_admits(caller, "publish_runtime_package", None, &package()).is_ok());
        assert!(mesh_admits(caller, "remove_runtime_version", Some("motherbee"), &remove).is_ok());
        let mut refused = Vec::new();
        for (field, value) in [
            ("test_hold_ms", json!(600_000)),
            ("sync_to", json!(["worker2"])),
            ("update_to", json!([])),
            ("target", json!("motherbee")),
        ] {
            let mut publish = package();
            publish[field] = value.clone();
            refused.push(("publish_runtime_package", publish));
            let mut removal = remove.clone();
            removal[field] = value;
            refused.push(("remove_runtime_version", removal));
        }
        let mut blob = package();
        blob["source"]["blob_path"] = json!("packages/wf.zip");
        refused.push(("publish_runtime_package", blob));
        for (action, params) in &refused {
            assert!(
                mesh_admits(caller, action, Some("motherbee"), params).is_err(),
                "{action} {params}"
            );
        }
        for (action, params) in &refused {
            assert!(
                mesh_admits("SY.architect@motherbee", action, Some("motherbee"), params).is_ok(),
                "{action} {params}"
            );
        }
    }

    /// SY.wf-rules asks only for the scan its deploys send (go/sy-wf-rules/node/admin.go), waiting
    /// at most 5 s: a longer wait, a missing one (the orchestrator's 30 s) or another field would
    /// let a worker hold the motherbee orchestrator's one-at-a-time system worker. Archi is not
    /// held to it.
    #[test]
    fn wf_rules_sync_hint_waits_at_most_five_seconds() {
        let caller = "SY.wf-rules@worker1";
        let scan = |wait_for_idle: bool, timeout_ms: Value| {
            json!({
                "channel": "dist",
                "folder_id": RUNTIMES_SYNC_FOLDER,
                "wait_for_idle": wait_for_idle,
                "timeout_ms": timeout_ms,
            })
        };
        // The deploy's wait and its nudge, as SyncRuntimes sends them.
        for params in [scan(true, json!(5000)), scan(false, json!(1000))] {
            assert_eq!(
                mesh_admits(caller, "sync_hint", Some("motherbee"), &params),
                Ok(MeshAdmission::Admitted),
                "{params}"
            );
        }
        let mut refused = vec![
            scan(true, json!(5001)),
            scan(true, json!(300_000)),
            scan(true, json!("5000")),
            scan(true, json!(-1)),
            json!({ "channel": "dist", "folder_id": RUNTIMES_SYNC_FOLDER, "wait_for_idle": true }),
        ];
        for (field, value) in [
            ("test_hold_ms", json!(1)),
            ("target", json!("motherbee")),
            ("category", json!("runtime")),
        ] {
            let mut extra = scan(true, json!(1000));
            extra[field] = value;
            refused.push(extra);
        }
        for params in &refused {
            assert!(
                mesh_admits(caller, "sync_hint", Some("motherbee"), params).is_err(),
                "{params}"
            );
            assert!(
                mesh_admits(
                    "SY.architect@motherbee",
                    "sync_hint",
                    Some("motherbee"),
                    params
                )
                .is_ok(),
                "{params}"
            );
        }
    }

    /// A purge (kill_node or remove_node_instance with the instance) waits for the node's
    /// teardown: SY.admin's window outlasts the orchestrator's 120 s for teardown_node and the
    /// motherbee's 150 s for a spoke's purge, so the caller gets the outcome, not a TIMEOUT while
    /// the work finishes.
    #[test]
    fn a_purge_outlasts_the_orchestrators_teardown_window() {
        for action in ["kill_node", "remove_node_instance"] {
            assert_eq!(
                admin_action_timeout(action),
                Duration::from_secs(180),
                "{action}"
            );
            assert!(admin_action_timeout(action) > Duration::from_secs(150));
        }
    }

    fn ilk_of(node_name: &str) -> Value {
        json!({
            "status": "ok",
            "ilk_id": TEST_ILK,
            "ilk": {
                "ilk_id": TEST_ILK,
                "ilk_type": "agent",
                "identification": { "node_name": node_name },
            },
        })
    }

    /// Answers each call of a teardown in turn, checking that it is the next one expected, and
    /// returns them as they were sent.
    async fn answer_teardown(
        harness: &mut fluxbee_sdk::RouterDispatcherTestHarness,
        replies: Vec<(&str, Value)>,
    ) -> Vec<Message> {
        let mut sent = Vec::new();
        for (expected, answer) in replies {
            let request = harness
                .next_outgoing_within(Duration::from_secs(5))
                .await
                .unwrap_or_else(|| panic!("{expected} was not sent"));
            assert_eq!(request.meta.msg.as_deref(), Some(expected));
            let done = reply_to(&request, &format!("{expected}_RESPONSE"), answer);
            harness.inject(done).await.unwrap();
            sent.push(request);
        }
        sent
    }

    /// `teardown_node` of `node_name` as its hive's orchestrator asks for it over the mesh.
    async fn teardown_of(
        ctx: &AdminContext,
        node_name: &str,
    ) -> Result<InternalAdminDispatchResult, AdminError> {
        let caller = format!(
            "SY.orchestrator@{}",
            node_name.rsplit_once('@').map(|(_, hive)| hive).unwrap()
        );
        dispatch_internal_admin_command(
            ctx,
            &ctx.rpc,
            "teardown_node",
            None,
            teardown_params(node_name),
            AdminOrigin::Mesh(&caller),
        )
        .await
    }

    /// teardown_node, in order: the ILK read (it must be the node's), the secrets dedicated to it,
    /// each in its own tenant, then the ILK marked and purged; the report shows every step.
    #[tokio::test]
    async fn teardown_node_removes_the_secrets_then_the_ilk() {
        let (ctx, mut harness) = mesh_test_admin("teardown-order");
        let (t1, t2) = (
            "tnt:11111111-1111-4111-8111-111111111111",
            "tnt:22222222-2222-4222-8222-222222222222",
        );
        let teardown = teardown_of(&ctx, "AI.sales@worker1");
        let drive = answer_teardown(
            &mut harness,
            vec![
                ("ILK_GET", ilk_of("AI.sales@worker1")),
                (
                    MSG_VAULT_LIST,
                    json!({ "status": "ok", "secrets": [
                        { "key": "slack:sales:bot", "metadata": { "tenant_id": t1 } },
                        { "key": "slack:sales:app", "metadata": { "tenant_id": t2 } },
                    ] }),
                ),
                (MSG_VAULT_DELETE, json!({ "status": "ok" })),
                (MSG_VAULT_DELETE, json!({ "status": "ok" })),
                ("ILK_DELETE", json!({ "status": "ok", "state": "deleted" })),
                ("ILK_PURGE", json!({ "status": "ok", "state": "purged" })),
            ],
        );
        let (result, sent) = tokio::join!(teardown, drive);
        let identity = json!(format!("SY.identity@{PRIMARY_HIVE_ID}"));
        let vault = json!(format!("SY.vault@{PRIMARY_HIVE_ID}"));
        let calls: Vec<(Value, Value)> = sent
            .iter()
            .map(|message| (dst_of(message), message.payload.clone()))
            .collect();
        assert_eq!(
            calls,
            vec![
                (identity.clone(), json!({ "ilk_id": TEST_ILK })),
                (
                    vault.clone(),
                    json!({ "filter": { "ilk": TEST_ILK, "limit": 1000 } })
                ),
                (
                    vault.clone(),
                    json!({ "key": "slack:sales:bot", "tenant_id": t1 })
                ),
                (vault, json!({ "key": "slack:sales:app", "tenant_id": t2 })),
                (identity.clone(), json!({ "ilk_id": TEST_ILK })),
                (identity, json!({ "ilk_id": TEST_ILK })),
            ]
        );
        let result = result.expect("dispatch");
        assert_eq!(result.http_status, 200, "{}", result.envelope);
        assert_eq!(result.envelope["status"], json!("ok"));
        assert_eq!(
            result.envelope["payload"],
            json!({
                "node_name": "AI.sales@worker1",
                "ilk_id": TEST_ILK,
                "ilk_deleted": true,
                "not_found": false,
                "vault_secrets_purged": { "status": "ok", "scanned": 2, "deleted": 2, "errors": [] },
                "ilk_delete": { "status": "ok" },
            })
        );
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

    /// An ILK that is not the node's: nothing is removed, and the answer says whose it is.
    #[tokio::test]
    async fn teardown_node_refuses_an_ilk_that_is_not_the_nodes() {
        let (ctx, mut harness) = mesh_test_admin("teardown-mismatch");
        let person = json!({ "status": "ok", "ilk": { "ilk_id": TEST_ILK, "ilk_type": "human", "identification": { "email": "a@b.c" } } });
        for (answer, owner) in [
            (ilk_of("AI.sales@worker2"), "AI.sales@worker2"),
            (person, "no node"),
        ] {
            let teardown = teardown_of(&ctx, "AI.sales@worker1");
            let drive = answer_teardown(&mut harness, vec![("ILK_GET", answer)]);
            let (result, _) = tokio::join!(teardown, drive);
            let result = result.expect("dispatch");
            assert_eq!(result.http_status, 409);
            assert_eq!(result.envelope["status"], json!("error"));
            assert_eq!(result.envelope["error_code"], json!("NODE_ILK_MISMATCH"));
            let detail = result.envelope["error_detail"].as_str().unwrap();
            assert!(detail.contains(owner), "{detail}");
            let payload = &result.envelope["payload"];
            assert_eq!(payload["ilk_deleted"], json!(false));
            assert_eq!(payload["vault_secrets_purged"]["status"], json!("skipped"));
            assert_eq!(payload["ilk_delete"], json!({ "status": "skipped" }));
            assert!(harness
                .next_outgoing_within(Duration::from_millis(200))
                .await
                .is_none());
        }
    }

    /// An ILK SY.identity does not hold: nothing ties its secrets to the node any more, so over the
    /// mesh they stay and the teardown is done; the operator's own teardown clears them. One that
    /// disappears between the read and the mark counts as done.
    #[tokio::test]
    async fn teardown_node_of_an_ilk_already_gone() {
        let (mut ctx, mut harness) = mesh_test_admin("teardown-not-found");
        let tenant = "tnt:11111111-1111-4111-8111-111111111111";
        let not_found =
            json!({ "status": "error", "error_code": "NOT_FOUND", "message": "failed to get ilk" });

        let teardown = teardown_of(&ctx, "IO.slack.sales@worker1");
        let drive = answer_teardown(&mut harness, vec![("ILK_GET", not_found.clone())]);
        let (result, _) = tokio::join!(teardown, drive);
        let result = result.expect("dispatch");
        assert_eq!(result.http_status, 200, "{}", result.envelope);
        assert_eq!(
            result.envelope["payload"],
            json!({
                "node_name": "IO.slack.sales@worker1",
                "ilk_id": TEST_ILK,
                "ilk_deleted": false,
                "not_found": true,
                "vault_secrets_purged": { "status": "skipped", "scanned": 0, "deleted": 0, "errors": [] },
                "ilk_delete": { "status": "skipped" },
            })
        );
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());

        // The operator, once the node is gone: the leftover secrets go.
        ctx.connected_nodes = Arc::new(|_| Ok(connected_now(&["worker1"], &["IO.other@worker1"])));
        let teardown = handle_admin_command(
            &ctx,
            &ctx.rpc,
            "teardown_node",
            teardown_params("IO.slack.sales@worker1"),
            Some("worker1".to_string()),
        );
        let drive = answer_teardown(
            &mut harness,
            vec![
                ("ILK_GET", not_found),
                (
                    MSG_VAULT_LIST,
                    json!({ "status": "ok", "secrets": [
                        { "key": "slack:sales:bot", "metadata": { "tenant_id": tenant } },
                    ] }),
                ),
                (MSG_VAULT_DELETE, json!({ "status": "ok" })),
            ],
        );
        let (result, _) = tokio::join!(teardown, drive);
        let (status, body) = result.expect("answered");
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 200, "{body}");
        assert_eq!(body["payload"]["not_found"], json!(true));
        assert_eq!(
            body["payload"]["vault_secrets_purged"],
            json!({ "status": "ok", "scanned": 1, "deleted": 1, "errors": [] })
        );
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());

        let teardown = teardown_of(&ctx, "IO.slack.sales@worker1");
        let drive = answer_teardown(
            &mut harness,
            vec![
                ("ILK_GET", ilk_of("IO.slack.sales@worker1")),
                (MSG_VAULT_LIST, json!({ "status": "ok", "secrets": [] })),
                (
                    "ILK_DELETE",
                    json!({ "status": "error", "error_code": "ILK_NOT_FOUND", "message": "gone" }),
                ),
            ],
        );
        let (result, _) = tokio::join!(teardown, drive);
        let result = result.expect("dispatch");
        assert_eq!(
            result.envelope["status"],
            json!("ok"),
            "{}",
            result.envelope
        );
        let payload = &result.envelope["payload"];
        assert_eq!(payload["not_found"], json!(true));
        assert_eq!(payload["ilk_deleted"], json!(false));
        assert_eq!(payload["ilk_delete"], json!({ "status": "ok" }));
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

    /// A node still connected is torn down only by its own orchestrator, right after its kill:
    /// the operator, Archi and the executor wait until shared memory no longer lists it. A node of
    /// a hive the LSA holds as stale, or does not list, while the registry still lists the hive is
    /// not read as gone: its hive is cut off, and it may run. Before 0.1.133 it was, and its secrets
    /// and its ILK went while it ran; a hive the registry no longer lists holds nothing up.
    #[test]
    fn a_connected_node_is_torn_down_only_by_its_own_orchestrator() {
        let registry = HiveRegistry::new(test_temp_dir("teardown-registry"));
        write_registry_entry(
            registry.root(),
            "worker1",
            "hive_id: worker1\nstatus: connected\nrole: worker\njoin:\n  phase: done\n",
        );
        let request =
            TeardownNodeRequest::from_params(&teardown_params("AI.sales@worker1")).unwrap();
        let own = AdminOrigin::Mesh("SY.orchestrator@worker1");
        assert_eq!(
            teardown_live_node_refusal(
                &request,
                own,
                PRIMARY_HIVE_ID,
                &registry,
                || -> Result<ConnectedNow, String> {
                    panic!("the orchestrator's own teardown reads nothing")
                }
            ),
            None
        );
        for origin in [
            AdminOrigin::Http,
            AdminOrigin::Executor,
            AdminOrigin::Mesh("SY.architect@motherbee"),
            AdminOrigin::Mesh("SY.orchestrator@worker2"),
        ] {
            let refusal = |connected: Result<ConnectedNow, String>| {
                teardown_live_node_refusal(&request, origin, PRIMARY_HIVE_ID, &registry, || {
                    connected
                })
            };
            let code = |connected: Result<ConnectedNow, String>| {
                refusal(connected).map(|(status, code, _)| (status, code))
            };
            assert_eq!(
                code(Ok(connected_now(&["worker1"], &["AI.sales@worker1"]))),
                Some((409, "NODE_STILL_CONNECTED")),
                "{origin:?}"
            );
            assert_eq!(
                code(Ok(connected_now(&["worker1"], &["AI.sales@worker2"]))),
                None
            );
            assert_eq!(
                code(Err("no regions".to_string())),
                Some((503, "INVENTORY_UNAVAILABLE"))
            );
            // worker1 stale in the LSA, or not in it, and still in the registry.
            let (status, code, detail) =
                refusal(Ok(connected_now(&["worker2"], &[]))).expect("refused");
            assert_eq!((status, code), (503, "INVENTORY_UNAVAILABLE"));
            assert_eq!(
                detail,
                "whether AI.sales@worker1 is still connected cannot be read: its hive worker1, \
                 which the hive registry still lists, is stale in the LSA or not in it; nothing \
                 was removed. Ask again once the hive is back, or remove the hive (remove_hive) if \
                 it is gone for good"
            );
        }
        // A hive the registry no longer lists: removed, nothing holds the teardown up.
        let gone = TeardownNodeRequest::from_params(&teardown_params("AI.sales@worker9")).unwrap();
        assert_eq!(
            teardown_live_node_refusal(
                &gone,
                AdminOrigin::Http,
                PRIMARY_HIVE_ID,
                &registry,
                || Ok(connected_now(&["worker1"], &[]))
            ),
            None
        );
        // A node of this admin's own hive is read from its routers' regions.
        let local =
            TeardownNodeRequest::from_params(&teardown_params("AI.sales@motherbee")).unwrap();
        assert_eq!(
            teardown_live_node_refusal(
                &local,
                AdminOrigin::Http,
                PRIMARY_HIVE_ID,
                &registry,
                || Ok(ConnectedNow::default())
            ),
            None
        );
        assert_eq!(error_code_to_http_status("NODE_STILL_CONNECTED"), 409);
        let _ = fs::remove_dir_all(registry.root());
    }

    /// Over HTTP: a connected node is refused before anything is sent, a box whose regions cannot
    /// be read waits, and a bare node name in the path is a node of the path's hive.
    #[tokio::test]
    async fn the_http_teardown_waits_for_the_node_to_be_gone() {
        let (mut ctx, mut harness) = mesh_test_admin("teardown-http");
        let ilk = serde_json::to_vec(&json!({ "ilk_id": TEST_ILK })).unwrap();
        let query = HashMap::new();
        let path = "/hives/worker1/nodes/WF.invoice/teardown";

        let (status, body) = handle_hive_paths("POST", path, &query, &ilk, &ctx, &ctx.rpc)
            .await
            .expect("answered")
            .expect("routed");
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 503, "{body}");
        assert_eq!(body["error_code"], json!("INVENTORY_UNAVAILABLE"));
        assert_eq!(body["payload"]["node_name"], json!("WF.invoice@worker1"));

        ctx.connected_nodes =
            Arc::new(|_| Ok(connected_now(&["worker1"], &["WF.invoice@worker1"])));
        let (status, body) = handle_hive_paths("POST", path, &query, &ilk, &ctx, &ctx.rpc)
            .await
            .expect("answered")
            .expect("routed");
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 409, "{body}");
        assert_eq!(body["error_code"], json!("NODE_STILL_CONNECTED"));
        assert_eq!(
            body["payload"]["vault_secrets_purged"]["status"],
            json!("skipped")
        );
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());

        // worker1 cut off, and still in the registry: its node may run, and nothing is sent.
        ctx.connected_nodes = Arc::new(|_| Ok(connected_now(&[], &[])));
        let (status, body) = handle_hive_paths("POST", path, &query, &ilk, &ctx, &ctx.rpc)
            .await
            .expect("answered")
            .expect("routed");
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 503, "{body}");
        assert_eq!(body["error_code"], json!("INVENTORY_UNAVAILABLE"));
        assert!(body["error_detail"]
            .as_str()
            .is_some_and(|detail| detail.contains("its hive worker1, which the hive registry")));
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());

        // Gone: the teardown runs, for the node of the path's hive.
        ctx.connected_nodes = Arc::new(|_| Ok(connected_now(&["worker1"], &[])));
        let teardown = handle_hive_paths("POST", path, &query, &ilk, &ctx, &ctx.rpc);
        let drive = answer_teardown(&mut harness, vec![("ILK_GET", ilk_of("WF.other@worker1"))]);
        let (result, _) = tokio::join!(teardown, drive);
        let (status, body) = result.expect("answered").expect("routed");
        let body: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(status, 409, "{body}");
        assert_eq!(body["error_code"], json!("NODE_ILK_MISMATCH"));
        assert_eq!(body["payload"]["node_name"], json!("WF.invoice@worker1"));
    }

    /// At start SY.admin logs the role each registered hive's nodes have over the mesh; these are
    /// the roles it logs.
    #[test]
    fn the_registry_roles_logged_at_start_are_the_tables() {
        let root = test_temp_dir("mesh-registry-roles");
        for (dir, info) in [
            (
                "worker1",
                "hive_id: worker1\nstatus: connected\nrole: worker\n",
            ),
            (
                "ingress1",
                "hive_id: ingress1\nstatus: connected\nrole: ingress\n",
            ),
            (
                "joining1",
                "hive_id: joining1\nstatus: joining\nrole: worker\njoin:\n  phase: accepted\n",
            ),
        ] {
            write_registry_entry(&root, dir, info);
        }
        fs::write(root.join("stray-file"), "not a hive").unwrap();
        assert_eq!(
            registry_caller_roles(PRIMARY_HIVE_ID, &HiveRegistry::new(&root)),
            vec![
                ("ingress1".to_string(), Some(CallerHive::Ingress)),
                ("joining1".to_string(), None),
                ("worker1".to_string(), Some(CallerHive::Worker)),
            ]
        );
        assert!(
            registry_caller_roles(PRIMARY_HIVE_ID, &HiveRegistry::new(root.join("absent")))
                .is_empty()
        );
    }

    /// A step that fails makes the teardown TEARDOWN_INCOMPLETE with the same report; a secret not
    /// deleted keeps the ILK for a retry, and nothing runs after an ILK read that failed.
    #[tokio::test]
    async fn teardown_node_reports_the_step_that_failed() {
        let (ctx, mut harness) = mesh_test_admin("teardown-failures");
        let tenant = "tnt:11111111-1111-4111-8111-111111111111";
        let failed = |code: &str, message: &str| json!({ "status": "error", "error_code": code, "message": message });

        // A secret SY.vault does not delete: the ILK stays.
        let teardown = teardown_of(&ctx, "AI.sales@worker1");
        let drive = answer_teardown(
            &mut harness,
            vec![
                ("ILK_GET", ilk_of("AI.sales@worker1")),
                (
                    MSG_VAULT_LIST,
                    json!({ "status": "ok", "secrets": [
                        { "key": "a", "metadata": { "tenant_id": tenant } },
                        { "key": "b", "metadata": { "tenant_id": tenant } },
                    ] }),
                ),
                (MSG_VAULT_DELETE, json!({ "status": "ok" })),
                (MSG_VAULT_DELETE, failed("STORAGE_ERROR", "disk full")),
            ],
        );
        let (result, _) = tokio::join!(teardown, drive);
        let result = result.expect("dispatch");
        assert_eq!(result.http_status, 502);
        assert_eq!(result.envelope["error_code"], json!("TEARDOWN_INCOMPLETE"));
        assert_eq!(
            result.envelope["payload"]["vault_secrets_purged"],
            json!({
                "status": "error",
                "scanned": 2,
                "deleted": 1,
                "errors": [{ "key": "b", "error_code": "STORAGE_ERROR", "error_detail": "disk full" }],
            })
        );
        assert_eq!(
            result.envelope["payload"]["ilk_delete"],
            json!({ "status": "skipped" })
        );
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());

        // A listing SY.vault refuses.
        let teardown = teardown_of(&ctx, "AI.sales@worker1");
        let drive = answer_teardown(
            &mut harness,
            vec![
                ("ILK_GET", ilk_of("AI.sales@worker1")),
                (MSG_VAULT_LIST, failed("VAULT_UNAVAILABLE", "sealed")),
            ],
        );
        let (result, _) = tokio::join!(teardown, drive);
        let result = result.expect("dispatch");
        assert_eq!(result.envelope["error_code"], json!("TEARDOWN_INCOMPLETE"));
        let vault = &result.envelope["payload"]["vault_secrets_purged"];
        assert_eq!(vault["status"], json!("error"));
        assert_eq!(vault["error_code"], json!("VAULT_UNAVAILABLE"));
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());

        // A purge SY.identity refuses: the ILK stays marked.
        let teardown = teardown_of(&ctx, "AI.sales@worker1");
        let drive = answer_teardown(
            &mut harness,
            vec![
                ("ILK_GET", ilk_of("AI.sales@worker1")),
                (MSG_VAULT_LIST, json!({ "status": "ok", "secrets": [] })),
                ("ILK_DELETE", json!({ "status": "ok", "state": "deleted" })),
                ("ILK_PURGE", failed("ILK_NOT_DELETED", "not marked")),
            ],
        );
        let (result, _) = tokio::join!(teardown, drive);
        let result = result.expect("dispatch");
        assert_eq!(result.envelope["error_code"], json!("TEARDOWN_INCOMPLETE"));
        let payload = &result.envelope["payload"];
        assert_eq!(payload["ilk_deleted"], json!(false));
        assert_eq!(payload["vault_secrets_purged"]["status"], json!("ok"));
        assert_eq!(
            payload["ilk_delete"],
            json!({ "status": "error", "error_code": "ILK_NOT_DELETED", "error_detail": "not marked" })
        );

        // An ILK read that fails: nothing is removed.
        let teardown = teardown_of(&ctx, "AI.sales@worker1");
        let drive = answer_teardown(
            &mut harness,
            vec![("ILK_GET", failed("DB_NOT_READY", "no database"))],
        );
        let (result, _) = tokio::join!(teardown, drive);
        let result = result.expect("dispatch");
        assert_eq!(result.http_status, 502);
        assert_eq!(result.envelope["error_code"], json!("TEARDOWN_INCOMPLETE"));
        let payload = &result.envelope["payload"];
        assert_eq!(payload["vault_secrets_purged"]["status"], json!("skipped"));
        assert_eq!(payload["ilk_delete"]["error_code"], json!("DB_NOT_READY"));
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

    /// What teardown_node takes: a node of the kind run_node launches and its ILK in canonical
    /// form; over HTTP, a node of the hive in the path. Refused before anything is sent.
    #[tokio::test]
    async fn teardown_node_validates_its_request_first() {
        let request =
            TeardownNodeRequest::from_params(&teardown_params("WF.billing.monthly@worker-2"))
                .expect("valid");
        assert_eq!(
            request,
            TeardownNodeRequest {
                node_name: "WF.billing.monthly@worker-2".to_string(),
                hive: "worker-2".to_string(),
                ilk_id: TEST_ILK.to_string(),
            }
        );
        let (ctx, mut harness) = mesh_test_admin("teardown-invalid");
        for params in [
            teardown_params("SY.admin@motherbee"),
            teardown_params("RT.gw@worker1"),
            teardown_params("AI.sales"),
            teardown_params("@worker1"),
            teardown_params(" AI.sales@worker1"),
            teardown_params("AI.sales@worker1@x"),
            teardown_params("AI.sales@../x"),
            json!({ "node_name": "AI.sales@worker1" }),
            json!({ "node_name": "AI.sales@worker1", "ilk_id": "ilk:not-a-uuid" }),
            json!({ "node_name": "AI.sales@worker1", "ilk_id": TEST_ILK.to_uppercase() }),
            json!({ "node_name": "AI.sales@worker1", "ilk_id": TEST_ILK.trim_start_matches("ilk:") }),
            json!({ "node_name": "AI.sales@worker1", "ilk_id": format!("{TEST_ILK} ") }),
        ] {
            let (status, body) =
                handle_admin_command(&ctx, &ctx.rpc, "teardown_node", params.clone(), None)
                    .await
                    .expect("answered");
            let body: Value = serde_json::from_str(&body).unwrap();
            assert_eq!(status, 400, "{params}: {body}");
            assert_eq!(body["error_code"], json!("INVALID_REQUEST"));
        }
        // The path's hive must be the node's.
        let (status, _) = handle_admin_command(
            &ctx,
            &ctx.rpc,
            "teardown_node",
            teardown_params("AI.sales@worker1"),
            Some("worker2".to_string()),
        )
        .await
        .expect("answered");
        assert_eq!(status, 400);
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

    /// teardown_node in the catalog: a mutation behind a confirmation, with its route, the hive
    /// taken from the node, and Archi and the executor able to call it.
    #[test]
    fn teardown_node_is_in_the_catalog() {
        let spec = resolve_internal_action_spec("teardown_node").expect("registered");
        assert!(spec.requires_target);
        let doc = build_admin_action_doc(spec);
        assert_eq!(doc["read_only"], json!(false));
        assert_eq!(doc["confirmation_required"], json!(true));
        assert_eq!(doc["executor_available"], json!(true));
        assert_eq!(
            doc["path_patterns"],
            json!(["POST /hives/{hive}/nodes/{node_name}/teardown"])
        );
        assert_ne!(doc["summary"], json!("Admin action."));
        let schema = &doc["executor_contract"]["function_schema"];
        assert_eq!(schema["required"], json!(["hive", "node_name", "ilk_id"]));
        assert!(admin_action_example_scmd("teardown_node").is_some());
        assert!(!admin_action_request_notes("teardown_node").is_empty());
        assert_eq!(
            admin_methods_allowed_for_path("/hives/worker1/nodes/AI.sales@worker1/teardown"),
            vec!["POST"]
        );
        assert_eq!(
            resolve_internal_action_hive("teardown_node", None, &teardown_params("AI.x@worker1")),
            Some("worker1".to_string())
        );
        assert_eq!(error_code_to_http_status("NODE_ILK_MISMATCH"), 409);
        assert_eq!(error_code_to_http_status("TEARDOWN_INCOMPLETE"), 502);
    }

    /// `ssh_allow_from` on add_hive: only with role ingress, an array of IPv4 or IPv6 addresses or
    /// CIDRs with their host bits clear.
    #[test]
    fn add_hive_takes_ssh_allow_from_only_for_an_ingress() {
        let add = |role: Option<&str>, allow: Value| {
            let mut payload =
                json!({ "hive_id": "ingress2", "address": "10.0.0.9", "ssh_user": "admin" });
            if let Some(role) = role {
                payload["role"] = json!(role);
            }
            payload["ssh_allow_from"] = allow;
            payload
        };
        for allow in [
            json!([]),
            json!(["192.168.8.0/24"]),
            json!(["10.0.0.7", "10.1.0.0/16", "0.0.0.0/0", "203.0.113.5/32"]),
            json!([
                "2001:db8::/32",
                "fe80::1",
                "::/0",
                "2001:db8::1/128",
                "::ffff:10.0.0.0/104"
            ]),
        ] {
            for role in ["ingress", " Ingress "] {
                assert_eq!(
                    admin_payload_contract_error("add_hive", &add(Some(role), allow.clone())),
                    None,
                    "{role} {allow}"
                );
            }
        }
        // Absent or null: nothing to check, whatever the role.
        let mut worker = add(None, json!(null));
        assert_eq!(admin_payload_contract_error("add_hive", &worker), None);
        worker.as_object_mut().unwrap().remove("ssh_allow_from");
        assert_eq!(admin_payload_contract_error("add_hive", &worker), None);
        // Only for an ingress.
        for role in [None, Some("worker"), Some("egress")] {
            let refusal =
                admin_payload_contract_error("add_hive", &add(role, json!(["10.0.0.0/8"])))
                    .expect("refused");
            assert!(refusal.contains("role ingress"), "{refusal}");
        }
        for allow in [
            json!("10.0.0.0/8"),
            json!([10]),
            json!(["10.0.0.0/33"]),
            json!(["10.0.0.0/"]),
            json!(["10.0.0.0/08"]),
            json!(["10.0.0.0/+8"]),
            json!(["2001:db8::/129"]),
            json!(["10.0.0.1/8"]),
            json!(["2001:db8::1/32"]),
            json!(["10.0.0.256"]),
            json!([" 10.0.0.0/8"]),
            json!(["10.0.0.0/8 "]),
            json!(["host.example"]),
            json!(["10.0.0.0/8; drop"]),
            json!(["[::1]"]),
            json!(["fe80::1%eth0"]),
        ] {
            assert!(
                admin_payload_contract_error("add_hive", &add(Some("ingress"), allow.clone()))
                    .is_some(),
                "{allow}"
            );
        }
        let refusal = admin_payload_contract_error(
            "add_hive",
            &add(Some("ingress"), json!(["192.168.8.10/24"])),
        )
        .unwrap();
        assert!(refusal.contains("192.168.8.0/24"), "{refusal}");
    }

    /// The add_hive the admin forwards to the orchestrator carries `ssh_allow_from` exactly as
    /// given; a refused one is never forwarded.
    #[tokio::test]
    async fn add_hive_passes_ssh_allow_from_through_unchanged() {
        let (ctx, mut harness) = opa_test_admin("add-hive-ssh-allow-from");
        let allow = json!(["192.168.8.0/24", "2001:db8::/32", "10.0.0.7"]);
        let payload = json!({
            "hive_id": "ingress2",
            "address": "10.0.0.9",
            "ssh_user": "admin",
            "role": "ingress",
            "ingress": { "listen": "0.0.0.0:443" },
            "ssh_allow_from": allow,
        });
        let add = handle_admin_command(&ctx, &ctx.rpc, "add_hive", payload, None);
        let drive = async {
            let sent = harness
                .next_outgoing_within(Duration::from_secs(5))
                .await
                .expect("the add_hive");
            assert_eq!(sent.meta.msg_type, "admin");
            assert_eq!(sent.meta.action.as_deref(), Some("add_hive"));
            assert_eq!(
                dst_of(&sent),
                json!(format!("SY.orchestrator@{PRIMARY_HIVE_ID}"))
            );
            assert_eq!(sent.payload["ssh_allow_from"], allow);
            let mut answer = reply_to(
                &sent,
                "",
                json!({ "status": "accepted", "hive_id": "ingress2" }),
            );
            answer.meta.msg_type = "admin".to_string();
            answer.meta.msg = None;
            harness.inject(answer).await.unwrap();
        };
        let (result, ()) = tokio::join!(add, drive);
        let (status, _) = result.expect("answered");
        assert_eq!(status, 202);

        let refused = json!({
            "hive_id": "worker9",
            "address": "10.0.0.10",
            "ssh_user": "admin",
            "ssh_allow_from": ["10.0.0.0/8"],
        });
        let (status, body) = handle_admin_command(&ctx, &ctx.rpc, "add_hive", refused, None)
            .await
            .expect("answered");
        assert_eq!(status, 400, "{body}");
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

    // --- The web hosts (docs/io-web-v2.md §11.1) ------------------------------------------

    const WEB_BASE_URL: &str = "https://hive-1.example.com";
    const WEB_ARCHI: &str = "archi.hive-1.example.com";

    fn web_section(text: &str) -> serde_yaml::Value {
        serde_yaml::from_str(text).expect("yaml")
    }

    #[test]
    fn web_declares_archi_before_the_host_of_the_public_base_url() {
        let web = WebConfig::from_hive(Some(&web_section("archi: true")), Some(WEB_BASE_URL));
        assert_eq!(
            web,
            WebConfig {
                hosts: vec![WEB_ARCHI.to_string()],
                error: None
            }
        );
        // The certified name's host: lowercase, with no trailing dot and no port.
        let web = WebConfig::from_hive(
            Some(&web_section("archi: true")),
            Some("https://Hive-1.Example.com.:443/base"),
        );
        assert_eq!(web.hosts, vec![WEB_ARCHI.to_string()]);
    }

    /// `web:` needs one key set: a bare `web:` reads as absent, as do `{}` and `archi: false`.
    #[test]
    fn a_bare_web_section_declares_nothing() {
        for text in [
            "hive_id: motherbee\nweb:\n",
            "hive_id: motherbee\nweb: {}\n",
            "hive_id: motherbee\nweb:\n  archi: false\n",
            "hive_id: motherbee\n",
        ] {
            let hive: HiveFile = serde_yaml::from_str(text).expect("hive.yaml");
            let web = WebConfig::from_hive(hive.web.as_ref(), Some(WEB_BASE_URL));
            assert_eq!(web, WebConfig::default(), "{text}");
        }
        let hive: HiveFile =
            serde_yaml::from_str("hive_id: motherbee\nweb:\n  archi: true\n").expect("hive.yaml");
        assert_eq!(
            WebConfig::from_hive(hive.web.as_ref(), Some(WEB_BASE_URL)).hosts,
            vec![WEB_ARCHI.to_string()]
        );
        assert_eq!(
            WebConfig::from_hive(Some(&serde_yaml::Value::Null), Some(WEB_BASE_URL)),
            WebConfig::default()
        );
    }

    #[test]
    fn a_web_section_that_cannot_work_declares_nothing_and_says_why() {
        for (text, base, why) in [
            (
                "archie: true",
                Some(WEB_BASE_URL),
                "web.archie is not a setting",
            ),
            ("archi: \"yes\"", Some(WEB_BASE_URL), "not true or false"),
            ("[archi]", Some(WEB_BASE_URL), "not a mapping"),
            ("archi: true", None, "admin.public_base_url is missing"),
            ("archi: true", Some("https://203.0.113.7"), "IP literal"),
        ] {
            let web = WebConfig::from_hive(Some(&web_section(text)), base);
            assert!(web.hosts.is_empty(), "{text}");
            let error = web.error.expect("a reason");
            assert!(error.contains(why), "{text}: {error}");
        }
    }

    fn web_routes(hosts: &[&str], edge: Result<&str, &str>) -> WebRoutes {
        let edge = edge.map(str::to_string).map_err(str::to_string);
        WebRoutes {
            config: WebConfig {
                hosts: hosts.iter().map(|host| host.to_string()).collect(),
                error: None,
            },
            edge: Arc::new(move || edge.clone()),
            timeout: Duration::from_secs(5),
            last: std::sync::Mutex::new(None),
        }
    }

    /// Each push carries the full set to the edge ACME addresses, and the edge's answer is kept:
    /// a refusal later keeps the time of the last acknowledgement.
    #[tokio::test]
    async fn the_web_routes_carry_the_full_set_and_the_edge_answer_is_kept() {
        let (ctx, mut harness) = opa_test_admin("web-routes");
        let routes = web_routes(&[WEB_ARCHI], Ok("SY.edge@ingress1"));
        let wait = Duration::from_secs(5);
        let drive = async {
            let sent = harness.next_outgoing_within(wait).await.expect("the push");
            assert_eq!(sent.meta.msg.as_deref(), Some(MSG_EDGE_WEB_ROUTES));
            assert_eq!(dst_of(&sent), json!("SY.edge@ingress1"));
            assert_eq!(sent.meta.target.as_deref(), Some("SY.edge@ingress1"));
            assert_eq!(
                sent.payload,
                json!({ "routes": [{ "host": WEB_ARCHI, "upstream": "io.web" }] })
            );
            let ok = reply_to(
                &sent,
                MSG_EDGE_WEB_ROUTES_RESPONSE,
                json!({
                    "status": "ok",
                    "upstream": {
                        "state": "ready",
                        "reason": null,
                        "last_failure": { "at": WEB_SINCE, "kind": "connect" },
                    },
                }),
            );
            harness.inject(ok).await.unwrap();
        };
        let ((first, changed), ()) = tokio::join!(routes.push_once(&ctx.rpc), drive);
        assert!(changed, "the first answer is news");
        assert_eq!(first.outcome, WebRoutesOutcome::Acknowledged);
        assert_eq!(first.edge.as_deref(), Some("SY.edge@ingress1"));
        assert_eq!(first.acknowledged_at, Some(first.since));
        assert_eq!(
            first.upstream,
            Some(EdgeWebUpstream {
                state: "ready".to_string(),
                reason: None,
                last_failure: Some(EdgeWebFailure {
                    at: WEB_SINCE,
                    kind: "connect".to_string(),
                }),
            }),
            "the edge's proxy, kept with the push"
        );

        let drive = async {
            let sent = harness.next_outgoing_within(wait).await.expect("the push");
            let refused = reply_to(
                &sent,
                MSG_EDGE_WEB_ROUTES_RESPONSE,
                json!({ "status": "error", "error_code": "INVALID_REQUEST", "message": "unknown upstream" }),
            );
            harness.inject(refused).await.unwrap();
        };
        let ((second, _), ()) = tokio::join!(routes.push_once(&ctx.rpc), drive);
        assert_eq!(
            second.outcome,
            WebRoutesOutcome::Refused("unknown upstream".to_string())
        );
        assert_eq!(second.acknowledged_at, first.acknowledged_at);
        assert_eq!(second.upstream, None, "only an acknowledgement reports it");
    }

    /// The whole answer is compared: the same refusal again is no news, another one is; a
    /// timeout is stated without its trace, so a repeated one is no news either.
    #[tokio::test]
    async fn only_a_change_of_answer_is_news() {
        let (ctx, mut harness) = opa_test_admin("web-routes-news");
        let routes = web_routes(&[WEB_ARCHI], Ok("SY.edge@ingress1"));
        let wait = Duration::from_secs(5);
        let mut news = Vec::new();
        for message in [
            "unknown upstream",
            "unknown upstream",
            "the routes file is read-only",
        ] {
            let drive = async {
                let sent = harness.next_outgoing_within(wait).await.expect("the push");
                let refused = reply_to(
                    &sent,
                    MSG_EDGE_WEB_ROUTES_RESPONSE,
                    json!({ "status": "error", "message": message }),
                );
                harness.inject(refused).await.unwrap();
            };
            let ((_, changed), ()) = tokio::join!(routes.push_once(&ctx.rpc), drive);
            news.push(changed);
        }
        assert_eq!(news, vec![true, false, true]);

        let silent = WebRoutes {
            timeout: Duration::from_millis(50),
            ..web_routes(&[WEB_ARCHI], Ok("SY.edge@ingress1"))
        };
        let (first, changed) = silent.push_once(&ctx.rpc).await;
        assert!(changed);
        assert_eq!(
            first.outcome,
            WebRoutesOutcome::NoAnswer("no answer in 50ms".to_string())
        );
        let (_, changed) = silent.push_once(&ctx.rpc).await;
        assert!(!changed, "a second timeout is the same answer");
        while harness
            .next_outgoing_within(Duration::from_millis(50))
            .await
            .is_some()
        {}
    }

    /// Without `web:` the set is empty, so a host taken out of `web:` leaves the edge; an edge
    /// that cannot take it is no answer, and no edge at all sends nothing.
    #[tokio::test]
    async fn without_web_the_edge_gets_an_empty_set() {
        let (ctx, mut harness) = opa_test_admin("web-routes-empty");
        let routes = web_routes(&[], Ok("SY.edge@ingress1"));
        let drive = async {
            let sent = harness
                .next_outgoing_within(Duration::from_secs(5))
                .await
                .expect("the push");
            assert_eq!(sent.payload, json!({ "routes": [] }));
            let blocked = reply_to(
                &sent,
                MSG_UNREACHABLE,
                json!({ "reason": "VPN_BLOCKED", "original_dst": "SY.edge@ingress1" }),
            );
            harness.inject(blocked).await.unwrap();
        };
        let ((push, _), ()) = tokio::join!(routes.push_once(&ctx.rpc), drive);
        assert!(
            matches!(&push.outcome, WebRoutesOutcome::NoAnswer(detail) if detail.contains("VPN_BLOCKED")),
            "{push:?}"
        );
        assert_eq!(push.acknowledged_at, None);

        let nowhere = web_routes(&[WEB_ARCHI], Err("no connected ingress hive"));
        let (push, _) = nowhere.push_once(&ctx.rpc).await;
        assert_eq!(
            push.outcome,
            WebRoutesOutcome::NoEdge("no connected ingress hive".to_string())
        );
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

    // --- GET /web/status (docs/io-web-v2.md §11.2) -----------------------------------------

    const WEB_IO_NODE: &str = "IO.web@motherbee";
    /// When the edge started to answer the way the last push records (Unix seconds).
    const WEB_SINCE: i64 = 1_792_700_000;

    /// How the test answers io.web's two reads: the orchestrator's view of the node and the
    /// node's own NODE_STATUS_GET.
    #[derive(Clone, Copy, Debug)]
    enum IoWebScript {
        /// The orchestrator has no IO.web@motherbee, and the router reaches no such node.
        Absent,
        /// The orchestrator sees it running, and it answers.
        Running,
        /// The orchestrator sees it running, and it does not answer.
        Silent,
        /// The orchestrator is still booting, and the node does not answer.
        Unknown,
    }

    /// Answer the two reads of one `GET /web/status` as `script` says.
    async fn answer_io_web_reads(
        harness: &mut fluxbee_sdk::RouterDispatcherTestHarness,
        script: IoWebScript,
    ) {
        for _ in 0..2 {
            let sent = harness
                .next_outgoing_within(Duration::from_secs(5))
                .await
                .expect("a read of io.web");
            if sent.meta.msg_type == "admin" {
                assert_eq!(sent.meta.action.as_deref(), Some("get_node_status"));
                assert_eq!(
                    dst_of(&sent),
                    json!(format!("SY.orchestrator@{PRIMARY_HIVE_ID}"))
                );
                assert_eq!(sent.payload["node_name"], WEB_IO_NODE);
                assert_eq!(sent.payload["target"], PRIMARY_HIVE_ID);
                let view = match script {
                    IoWebScript::Absent => json!({
                        "status": "error",
                        "error_code": "NODE_NOT_FOUND",
                        "message": "node 'IO.web@motherbee' not found",
                    }),
                    IoWebScript::Running | IoWebScript::Silent => json!({
                        "status": "ok",
                        "node_name": WEB_IO_NODE,
                        "node_status": {
                            "node_name": WEB_IO_NODE,
                            "lifecycle_state": "RUNNING",
                            "health_state": "HEALTHY",
                            "runtime": { "name": "io.web", "resolved_version": "0.1.85" },
                        },
                    }),
                    IoWebScript::Unknown => json!({
                        "status": "error",
                        "error_code": "ORCHESTRATOR_BOOTING",
                        "message": "the orchestrator is still booting; retry shortly",
                    }),
                };
                let mut answer = reply_to(&sent, "", view);
                answer.meta.msg_type = "admin".to_string();
                answer.meta.msg = None;
                harness.inject(answer).await.unwrap();
            } else {
                assert_eq!(sent.meta.msg.as_deref(), Some(MSG_NODE_STATUS_GET));
                assert_eq!(dst_of(&sent), json!(WEB_IO_NODE));
                let answer = match script {
                    IoWebScript::Absent => Some(reply_to(
                        &sent,
                        MSG_UNREACHABLE,
                        json!({ "reason": "NODE_NOT_FOUND", "original_dst": WEB_IO_NODE }),
                    )),
                    IoWebScript::Running => Some(reply_to(
                        &sent,
                        MSG_NODE_STATUS_GET_RESPONSE,
                        json!({
                            "status": "ok",
                            "health_state": "HEALTHY",
                            "lifecycle_state": "CONFIGURED",
                        }),
                    )),
                    IoWebScript::Silent | IoWebScript::Unknown => None,
                };
                if let Some(answer) = answer {
                    harness.inject(answer).await.unwrap();
                }
            }
        }
    }

    /// One `GET /web/status` payload, with io.web's reads answered as `script` says; the node's
    /// own answer is waited for 100 ms.
    async fn web_status_with(
        ctx: &AdminContext,
        harness: &mut fluxbee_sdk::RouterDispatcherTestHarness,
        script: IoWebScript,
    ) -> Value {
        let status = web_status_payload(
            ctx,
            &ctx.rpc,
            Duration::from_secs(5),
            Duration::from_millis(100),
        );
        let (payload, ()) = tokio::join!(status, answer_io_web_reads(harness, script));
        payload
    }

    fn with_last_push(routes: WebRoutes, push: Option<WebRoutesPush>) -> Arc<WebRoutes> {
        *routes.last.lock().unwrap() = push;
        Arc::new(routes)
    }

    /// The routes as the edge last answered them: acknowledged (with the edge's proxy, ready or
    /// not), refused, not pushed yet, and no edge to push them to. Each with the full set the
    /// pushes carry.
    #[tokio::test]
    async fn the_web_status_names_the_edges_last_answer_to_the_routes() {
        let (mut ctx, mut harness) = opa_test_admin("web-status-routes");
        let set = json!([{ "host": WEB_ARCHI, "upstream": "io.web" }]);
        let edge = "SY.edge@ingress1";
        let acknowledged_at = WEB_SINCE + 600;
        let failed_at = WEB_SINCE + 300;
        let acknowledged = |upstream: EdgeWebUpstream| WebRoutesPush {
            edge: Some(edge.to_string()),
            outcome: WebRoutesOutcome::Acknowledged,
            since: WEB_SINCE,
            acknowledged_at: Some(acknowledged_at),
            upstream: Some(upstream),
        };
        let no_material = "mesh TLS material in /var/lib/fluxbee/tls/ingress1: io: not found";
        for (push, state, detail, last_acknowledged, upstream) in [
            (
                Some(acknowledged(EdgeWebUpstream {
                    state: "ready".to_string(),
                    reason: None,
                    last_failure: Some(EdgeWebFailure {
                        at: failed_at,
                        kind: "handshake".to_string(),
                    }),
                })),
                "acknowledged",
                None,
                Some(acknowledged_at),
                json!({
                    "state": "ready",
                    "reason": null,
                    "last_failure": { "at": unix_rfc3339(failed_at), "kind": "handshake" },
                }),
            ),
            // The routes acknowledged, and no way to io.web: every web host answers 502.
            (
                Some(acknowledged(EdgeWebUpstream {
                    state: "unavailable".to_string(),
                    reason: Some(no_material.to_string()),
                    last_failure: None,
                })),
                "acknowledged",
                None,
                Some(acknowledged_at),
                json!({ "state": "unavailable", "reason": no_material, "last_failure": null }),
            ),
            (
                Some(WebRoutesPush {
                    edge: Some(edge.to_string()),
                    outcome: WebRoutesOutcome::Refused("unknown upstream".to_string()),
                    since: WEB_SINCE,
                    acknowledged_at: Some(acknowledged_at),
                    upstream: None,
                }),
                "refused",
                Some("unknown upstream"),
                Some(acknowledged_at),
                Value::Null,
            ),
            (None, "not_pushed", None, None, Value::Null),
            (
                Some(WebRoutesPush {
                    edge: None,
                    outcome: WebRoutesOutcome::NoEdge("no connected ingress hive".to_string()),
                    since: WEB_SINCE,
                    acknowledged_at: None,
                    upstream: None,
                }),
                "no_edge",
                Some("no connected ingress hive"),
                None,
                Value::Null,
            ),
        ] {
            let pushed = push.is_some();
            let edge_of_push = push.as_ref().and_then(|push| push.edge.clone());
            ctx.web = with_last_push(web_routes(&[WEB_ARCHI], Ok(edge)), push);
            let payload = web_status_with(&ctx, &mut harness, IoWebScript::Absent).await;
            let routes = &payload["routes"];
            assert_eq!(routes["state"], state, "{payload}");
            assert_eq!(routes["set"], set, "{state}");
            assert_eq!(routes["edge"], json!(edge_of_push), "{state}");
            assert_eq!(routes["detail"], json!(detail), "{state}");
            assert_eq!(
                routes["since_at"],
                json!(pushed.then(|| unix_rfc3339(WEB_SINCE))),
                "{state}"
            );
            assert_eq!(
                routes["acknowledged_at"],
                json!(last_acknowledged.map(unix_rfc3339)),
                "{state}"
            );
            assert_eq!(routes["upstream"], upstream, "{state}");
            assert_eq!(payload["web"]["state"], "declared");
            assert_eq!(payload["web"]["hosts"], json!([WEB_ARCHI]));
        }
    }

    /// io.web absent, running and silent, and unknown when neither read says: each a state, never
    /// an error.
    #[tokio::test]
    async fn the_web_status_names_io_webs_state() {
        let (ctx, mut harness) = opa_test_admin("web-status-io-web");
        let absent = web_status_with(&ctx, &mut harness, IoWebScript::Absent).await;
        let io_web = &absent["io_web"];
        assert_eq!(io_web["node"], WEB_IO_NODE);
        assert_eq!(io_web["state"], "absent", "{absent}");
        assert_eq!(io_web["lifecycle_state"], Value::Null);
        assert_eq!(io_web["view_error"], Value::Null, "no node is no error");
        assert_eq!(io_web["answer"], Value::Null);
        assert!(
            io_web["answer_error"]
                .as_str()
                .is_some_and(|detail| detail.contains("NODE_NOT_FOUND")),
            "{io_web}"
        );

        let running = web_status_with(&ctx, &mut harness, IoWebScript::Running).await;
        let io_web = &running["io_web"];
        assert_eq!(io_web["state"], "running", "{running}");
        assert_eq!(io_web["lifecycle_state"], "RUNNING");
        assert_eq!(io_web["runtime_version"], "0.1.85");
        assert_eq!(io_web["answer"]["health_state"], "HEALTHY");
        assert_eq!(io_web["answer_error"], Value::Null);

        let silent = web_status_with(&ctx, &mut harness, IoWebScript::Silent).await;
        let io_web = &silent["io_web"];
        assert_eq!(io_web["state"], "silent", "{silent}");
        assert_eq!(io_web["lifecycle_state"], "RUNNING");
        assert_eq!(io_web["answer"], Value::Null);
        assert_eq!(io_web["answer_error"], "no answer in 100ms");

        let unknown = web_status_with(&ctx, &mut harness, IoWebScript::Unknown).await;
        let io_web = &unknown["io_web"];
        assert_eq!(io_web["state"], "unknown", "{unknown}");
        assert!(
            io_web["view_error"]
                .as_str()
                .is_some_and(|detail| detail.contains("booting")),
            "{io_web}"
        );
    }

    /// The node's own answer says it runs, whatever the orchestrator; without it, the
    /// orchestrator's lifecycle names the state.
    #[test]
    fn io_webs_state_comes_from_its_answer_then_from_the_orchestrator() {
        let found = |lifecycle: &str| IoWebView::Found(json!({ "lifecycle_state": lifecycle }));
        for (view, answered, state) in [
            (found("STOPPED"), true, "running"),
            (
                IoWebView::Unavailable("no answer".to_string()),
                true,
                "running",
            ),
            (found("RUNNING"), false, "silent"),
            (found("STARTING"), false, "starting"),
            (found("STOPPED"), false, "stopped"),
            (found("FAILED"), false, "failed"),
            (found("UNKNOWN"), false, "unknown"),
            (IoWebView::NotFound, false, "absent"),
            (
                IoWebView::Unavailable("no answer".to_string()),
                false,
                "unknown",
            ),
        ] {
            assert_eq!(io_web_state(&view, answered), state, "{view:?} {answered}");
        }
    }

    /// Through the dispatcher, as the HTTP route reaches it: 200 with every part, without `web:`
    /// and with no edge; a parameter is refused.
    #[tokio::test]
    async fn web_status_answers_200_without_web_and_without_an_edge() {
        let (ctx, mut harness) = opa_test_admin("web-status-dispatch");
        let status = dispatch_internal_admin_command(
            &ctx,
            &ctx.rpc,
            "web_status",
            None,
            json!({}),
            AdminOrigin::Http,
        );
        let (result, ()) = tokio::join!(
            status,
            answer_io_web_reads(&mut harness, IoWebScript::Running)
        );
        let result = result.expect("answered");
        assert_eq!(result.http_status, 200, "{}", result.envelope);
        let payload = &result.envelope["payload"];
        assert_eq!(result.envelope["status"], "ok");
        assert_eq!(
            payload["web"],
            json!({ "state": "absent", "hosts": [], "reason": null })
        );
        assert_eq!(payload["certificate"]["acme"], "absent");
        assert_eq!(payload["routes"]["state"], "not_pushed");
        assert_eq!(payload["routes"]["set"], json!([]));
        assert_eq!(payload["io_web"]["state"], "running");
        assert!(payload["now_at"].is_string());

        let refused = dispatch_internal_admin_command(
            &ctx,
            &ctx.rpc,
            "web_status",
            None,
            json!({ "host": WEB_ARCHI }),
            AdminOrigin::Http,
        )
        .await
        .expect("answered");
        assert_eq!(refused.http_status, 400);
        assert_eq!(refused.envelope["error_code"], "INVALID_REQUEST");
        assert!(harness
            .next_outgoing_within(Duration::from_millis(200))
            .await
            .is_none());
    }

